1	//! A checker type converted to [`PropType`] from the checker's structured answers: type flags, a union's members, a
2	//! reference's type arguments, a tuple's element flags, an object's properties, index and call signatures, an alias's
3	//! symbol and arguments. The printed type (`typeToString`) names things for display and for the two facts the
4	//! structure does not state (see [`crate::printed`]); no shape is read from it.
5	//!
6	//! The conversion of a type is a function of the type, how deep it sits and which instantiations enclose it, never of
7	//! the order the checker was asked in, so the memo can be keyed by the checker's type handle (valid inside one
8	//! snapshot) without making the output depend on query order. A handle is also what tells one instantiation from
9	//! another while a type is being expanded (`Box<Box<string>>` is two instantiations of one declaration): only its
10	//! equality is read, inside one conversion, so the answer does not depend on the numbers. The recursion marker that
11	//! results is named by the declaration (the alias or interface) and holds no handle. The memo is keyed by the enclosing
12	//! instantiations a conversion actually asked about, not by all of them (see [`State::memo`]).
13	//!
14	//! Every descent into the parts of a type (members, properties, elements, holes) passes [`Converter::enter`], which
15	//! decides before anything is fetched or converted whether the type is an enclosing instantiation (a back-reference),
16	//! sits too deep, or is too wide.
17	//!
18	//! What stays a name instead of an expansion, the named boundary: an object type declared in a dependency
19	//! (`node_modules`) or an interface or class of the TypeScript lib (`Date`, `HTMLElement`, `Promise<T>`), with its type
20	//! arguments; a function type is always expanded, since its parameters are what a reader wants. The lib's type-level
21	//! utilities (`Partial`, `Pick`, `Omit`, `Record`) are evaluated, not named: their result is the type, unless it is
22	//! wider than the budget and what it applies to has a name (see [`Converter::over_budget`]). A dependency's union of
23	//! literals is expanded too, since its members are the values a control offers. What the caps cut is a typed
24	//! [`PropType::Truncated`], never the checker's text standing in as a name. The width of an object counts only the
25	//! members the project did not declare: its own are listed whole.
26	
27	use std::future::Future;
28	use std::pin::Pin;
29	use std::sync::atomic::{AtomicU64, Ordering};
30	use std::sync::{Arc, Mutex};
31	
32	use caliper_docgen_core::react_types::{html_element_for, html_element_from_type_arg, is_intrinsic_tag};
33	use caliper_docgen_core::types::semantic::{degraded_type, unresolved_type};
34	use caliper_docgen_core::types::{
35	    BigIntValue, CallSignature, EnumMemberValue, FunctionParam, ObjectField, OpaqueReason, PropType,
36	    SignatureKind as Kind, TemplatePart, TruncationLimit, TupleElement, TupleElementKind, TupleLabel,
37	};
38	use rustc_hash::FxHashMap;
39	
40	use crate::printed::{Marker, SignatureMarkers, signature_markers, tuple_labels};
41	use crate::rpc::{
42	    CallError, CompactSymbol, ObjectMembers, Rpc, SignatureInfo, SignatureKind, SymbolInfo, TypeInfo, flag,
43	};
44	
45	/// Nesting past which an object, union or intersection is cut with [`TruncationLimit::Depth`].
46	const MAX_DEPTH: u8 = 5;
47	/// The most properties an object type lists at the top (a prop's own type) and below it that the project did not declare
48	/// itself (see [`is_own`]): what it declared is never cut.
49	const MAX_FIELDS: [usize; 2] = [100, 40];
50	/// The most members a union or intersection lists at the top and below it.
51	const MAX_MEMBERS: [usize; 2] = [500, 120];
52	/// How many of React's tag names (see [`is_tag`]) a union has to list to be React's `ElementType` (`JSX.IntrinsicElements`
53	/// has over 170): the tag names are the one part of it that no declaration identifies.
54	const MIN_INTRINSIC_TAGS: usize = 100;
55	/// The lib's utility aliases that keep the properties of the type they are applied to, and so can stand for it.
56	const UTILITIES: [&str; 5] = ["Omit", "Pick", "Partial", "Required", "Readonly"];
57	
58	/// What a descent found at [`Converter::enter`].
59	enum Gate<T> {
60	    /// The type is not expanded: it is a back-reference, or a cap cut it.
61	    Stop(PropType),
62	    /// The parts of the type, and the context to convert them in.
63	    Open { parts: T, inner: Cx },
64	}
65	
66	type Converted<'a> = Pin<Box<dyn Future<Output = Result<PropType, CallError>> + Send + 'a>>;
67	
68	/// Where a type sits: how deep, and which named instantiations (an alias or interface with its type arguments, as the
69	/// checker's type handle) enclose it, outermost first.
70	#[derive(Debug, Clone, Default)]
71	pub(crate) struct Cx {
72	    depth: u8,
73	    enclosing: Arc<Vec<u64>>,
74	    /// The conversion this context belongs to, which records which enclosing instantiations it asks about. `None` at
75	    /// the roots.
76	    frame: Option<Arc<Frame>>,
77	}
78	
79	/// What one conversion has asked of the instantiations enclosing it, kept to build its memo entry (see
80	/// [`State::memo`]).
81	#[derive(Debug)]
82	struct Frame {
83	    /// How many instantiations enclosed the type when its conversion began: those below this are the outer context, the
84	    /// rest were opened by the conversion itself.
85	    base: usize,
86	    asked: Mutex<Asked>,
87	}
88	
89	#[derive(Debug, Default)]
90	struct Asked {
91	    /// The handles this conversion's own gate compared against its enclosing instantiations.
92	    ids: Vec<u64>,
93	    /// The sets asked by the conversions of its parts, each with the instantiations this conversion had opened by then:
94	    /// those were answered inside it and do not depend on its outer context.
95	    parts: Vec<(Arc<[u64]>, Vec<u64>)>,
96	}
97	
98	impl Frame {
99	    fn new(base: usize) -> Self {
100	        Frame { base, asked: Mutex::default() }
101	    }
102	
103	    fn lock(&self) -> std::sync::MutexGuard<'_, Asked> {
104	        self.asked.lock().unwrap_or_else(std::sync::PoisonError::into_inner)
105	    }
106	
107	    fn ask(&self, id: u64) {
108	        self.lock().ids.push(id);
109	    }
110	
111	    /// A part of this conversion was converted (or recalled) under `enclosing`, having asked about `asked`.
112	    fn absorb(&self, asked: &Arc<[u64]>, enclosing: &[u64]) {
113	        if !asked.is_empty() {
114	            self.lock().parts.push((asked.clone(), enclosing.get(self.base..).unwrap_or_default().to_vec()));
115	        }
116	    }
117	
118	    /// Every handle the conversion asked about whose answer came from outside it: sorted, once each.
119	    fn finish(&self) -> Arc<[u64]> {
120	        let asked = self.lock();
121	        let mut ids = asked.ids.clone();
122	        for (part, opened) in &asked.parts {
123	            ids.extend(part.iter().copied().filter(|id| !opened.contains(id)));
124	        }
125	        ids.sort_unstable();
126	        ids.dedup();
127	        ids.into()
128	    }
129	}
130	
131	impl Cx {
132	    /// The context of what a name carries, its type arguments: one level down. Each argument is converted on its own
133	    /// and passes [`Converter::enter`] if it has parts.
134	    fn argument(&self) -> Cx {
135	        Cx { depth: self.depth.saturating_add(1), enclosing: self.enclosing.clone(), frame: self.frame.clone() }
136	    }
137	
138	    /// The context of the parts of a type that [`Converter::enter`] has admitted. Only a named instance is kept, since
139	    /// only a name can be pointed back to.
140	    fn below(&self, instance: Option<u64>) -> Cx {
141	        let mut enclosing = self.enclosing.clone();
142	        if let Some(id) = instance
143	            && !enclosing.contains(&id)
144	        {
145	            let mut grown = (*enclosing).clone();
146	            grown.push(id);
147	            enclosing = Arc::new(grown);
148	        }
149	        Cx { depth: self.depth.saturating_add(1), enclosing, frame: self.frame.clone() }
150	    }
151	
152	    /// Whether `id` is an instantiation being expanded around the type. The conversion in progress is recorded to have
153	    /// asked, whichever the answer.
154	    fn encloses(&self, id: u64) -> bool {
155	        if let Some(frame) = &self.frame {
156	            frame.ask(id);
157	        }
158	        self.enclosing.contains(&id)
159	    }
160	
161	    fn limit<const N: usize>(&self, limits: [usize; N]) -> usize {
162	        limits[usize::from(self.depth > 0).min(N - 1)]
163	    }
164	}
165	
166	/// What declares a type: the alias it was written through, else its interface or class.
167	#[derive(Debug, Clone)]
168	struct Origin {
169	    name: String,
170	    /// The declaring file as the checker keys it (lower-cased path).
171	    file: String,
172	    alias: bool,
173	}
174	
175	impl Origin {
176	    fn of(symbol: &SymbolInfo, alias: bool) -> Self {
177	        let declaration = symbol.declarations.first().map(String::as_str);
178	        Origin {
179	            name: symbol.name.clone(),
180	            file: declaration.map(|declaration| declared_in(declaration).to_string()).unwrap_or_default(),
181	            alias,
182	        }
183	    }
184	
185	    fn in_dependency(&self) -> bool {
186	        file_in_dependency(&self.file)
187	    }
188	
189	    fn in_lib(&self) -> bool {
190	        file_in_lib(&self.file)
191	    }
192	
193	    fn in_react(&self) -> bool {
194	        self.file.contains("/@types/react/")
195	    }
196	
197	    /// Whether the name stands for the type: declared in a dependency, or an interface or class of the lib. An alias
198	    /// of the lib is a type-level function (`Partial<T>`), and its result is the type.
199	    fn is_boundary(&self) -> bool {
200	        // The lib may itself sit under `node_modules` (`typescript/lib`, `@tsrs/<platform>`).
201	        if self.in_lib() { !self.alias } else { self.in_dependency() }
202	    }
203	
204	    /// The React type that PropType holds as a terminal, found by the declaration and not by how it prints.
205	    fn react_terminal(&self) -> Option<PropType> {
206	        if !self.in_react() {
207	            return None;
208	        }
209	        match (self.name.as_str(), self.alias) {
210	            ("ReactNode", true) | ("ReactElement" | "Element", false) => Some(PropType::ReactNode),
211	            ("ElementType", true) => Some(PropType::ElementType),
212	            ("CSSProperties", false) => Some(PropType::CssProperties),
213	            _ => None,
214	        }
215	    }
216	}
217	
218	/// Whether a union member is a tag of React's `JSX.IntrinsicElements`: a string literal (not an enum member) whose value
219	/// that table lists. A literal the checker gave no value for is not one, so it is kept beside the terminal.
220	fn is_tag(member: &TypeInfo) -> bool {
221	    member.flags & flag::STRING_LITERAL != 0
222	        && member.flags & flag::ENUM_LITERAL == 0
223	        && member.value.as_ref().and_then(|value| value.as_str()).is_some_and(is_intrinsic_tag)
224	}
225	
226	/// Whether the checker states the base types of this type: the declaration of a class or interface does, in its own
227	/// terms. An instantiation of a generic one (`Box<string>`, only a reference) does not state them in terms of its
228	/// arguments, so what it inherits cannot be listed from its bases.
229	fn states_bases(info: &TypeInfo) -> bool {
230	    info.object_flags & (flag::OBJECT_CLASS | flag::OBJECT_INTERFACE) != 0
231	}
232	
233	fn file_in_dependency(file: &str) -> bool {
234	    file.contains("/node_modules/")
235	}
236	
237	fn file_in_lib(file: &str) -> bool {
238	    let name = file.rsplit('/').next().unwrap_or("");
239	    name.starts_with("lib.") && name.ends_with(".d.ts")
240	}
241	
242	/// Whether a property is the project's own: its first declaration is in a file of the project, not a dependency or the
243	/// lib. A property with no declaration (a mapped type's synthetic one) is not, so a wide mapped type is still cut.
244	fn is_own(property: &SymbolInfo) -> bool {
245	    property.declarations.first().is_some_and(|declaration| {
246	        let file = declared_in(declaration);
247	        !file_in_dependency(file) && !file_in_lib(file)
248	    })
249	}
