256	/// A converted type, with the enclosing instantiations its conversion depended on.
257	#[derive(Debug)]
258	struct Entry {
259	    /// Every handle the conversion compared against the instantiations enclosing it, sorted.
260	    asked: Arc<[u64]>,
261	    /// Those of `asked` that did enclose it.
262	    enclosed_by: Vec<u64>,
263	    converted: PropType,
264	}
265	
266	impl Entry {
267	    /// Whether the conversion would go the same way inside `enclosing`: among the handles it asked about, the ones
268	    /// that enclose the type there are exactly `enclosed_by`.
269	    fn holds_in(&self, enclosing: &[u64]) -> bool {
270	        self.enclosed_by.iter().all(|id| enclosing.contains(id))
271	            && enclosing.iter().all(|id| self.enclosed_by.contains(id) || self.asked.binary_search(id).is_err())
272	    }
273	}
274	
275	type Memo = Mutex<FxHashMap<(u64, u8), Vec<Arc<Entry>>>>;
276	
277	#[derive(Default)]
278	struct State {
279	    /// Conversions by (type handle, depth), each entry with the enclosing instantiations it depended on. The handles
280	    /// are valid inside this snapshot only.
281	    ///
282	    /// Why an entry may be reused where [`Entry::holds_in`] says. A conversion reads its context in two ways only: the
283	    /// depth, which is in the key, and [`Cx::encloses`], the question whether a handle is an instantiation being
284	    /// expanded around the type. Everything else it reads is the checker's answer about the type, which does not change
285	    /// inside a snapshot. So a conversion is a deterministic walk whose every step is fixed by the type, the depth and
286	    /// the answers to those questions, in the order they are asked. Run it again where each handle it asked about has
287	    /// the same answer, and it asks the same questions in the same order and returns the same type. A handle that the
288	    /// conversion opened itself is settled inside it (it was found not to enclose the type at its own gate, which is
289	    /// recorded), so only the handles asked of the outer context are kept. A type in no cycle with its context asks
290	    /// nothing that encloses it and holds everywhere; one in a cycle holds where the same part of the cycle encloses
291	    /// it. Entries that hold in a context all agree, so which of them is found first, and so the order in which
292	    /// types were first reached, cannot show in the output.
293	    memo: Memo,
294	    origins: Mutex<FxHashMap<(bool, CompactSymbol), Option<Origin>>>,
295	    /// By (type handle, whether printed expanded: see [`Rpc::type_to_string_expanded`]).
296	    printed: Mutex<FxHashMap<(u64, bool), String>>,
297	    hits: AtomicU64,
298	    misses: AtomicU64,
299	}
