301	#[derive(Clone)]
302	pub(crate) struct Converter {
303	    rpc: Arc<Rpc>,
304	    state: Arc<State>,
305	    /// Ask the checker about the members of a type last to first. The answer is the same, and a test holds it to that.
306	    reverse: bool,
307	}
308	
309	impl Converter {
310	    pub(crate) fn new(rpc: Arc<Rpc>, reverse: bool) -> Self {
311	        Self { rpc, state: Arc::new(State::default()), reverse }
312	    }
313	
314	    /// Every type converted, in the order of `infos`, though when `reverse` is set the checker is asked last to first.
315	    async fn convert_all(&self, infos: &[TypeInfo], cx: &Cx) -> Result<Vec<PropType>, CallError> {
316	        let mut slots: Vec<Option<PropType>> = vec![None; infos.len()];
317	        let order: Box<dyn Iterator<Item = usize> + Send> =
318	            if self.reverse { Box::new((0..infos.len()).rev()) } else { Box::new(0..infos.len()) };
319	        for index in order {
320	            if let (Some(info), Some(slot)) = (infos.get(index), slots.get_mut(index)) {
321	                *slot = Some(self.convert(info, cx).await?);
322	            }
323	        }
324	        Ok(slots.into_iter().flatten().collect())
325	    }
326	
327	    /// Memo hits and misses so far, for the debug line.
328	    pub(crate) fn memo_stats(&self) -> (u64, u64) {
329	        (self.state.hits.load(Ordering::Relaxed), self.state.misses.load(Ordering::Relaxed))
330	    }
331	
332	    /// The own types of a component's props, from the top.
333	    pub(crate) async fn convert_roots(&self, infos: &[TypeInfo]) -> Result<Vec<PropType>, CallError> {
334	        self.convert_all(infos, &Cx::default()).await
335	    }
336	
337	    fn convert<'a>(&'a self, info: &'a TypeInfo, cx: &'a Cx) -> Converted<'a> {
338	        Box::pin(async move {
339	            if let Some(entry) = self.recall(info.id, cx) {
340	                self.state.hits.fetch_add(1, Ordering::Relaxed);
341	                if let Some(frame) = &cx.frame {
342	                    frame.absorb(&entry.asked, &cx.enclosing);
343	                }
344	                return Ok(entry.converted.clone());
345	            }
346	            self.state.misses.fetch_add(1, Ordering::Relaxed);
347	            let frame = Arc::new(Frame::new(cx.enclosing.len()));
348	            let own = Cx { depth: cx.depth, enclosing: cx.enclosing.clone(), frame: Some(frame.clone()) };
349	            let converted = self.uncached(info, &own).await?;
350	            let asked = frame.finish();
351	            if let Some(parent) = &cx.frame {
352	                parent.absorb(&asked, &cx.enclosing);
353	            }
354	            let enclosed_by = cx.enclosing.iter().copied().filter(|id| asked.binary_search(id).is_ok()).collect();
355	            let entry = Arc::new(Entry { asked, enclosed_by, converted: converted.clone() });
356	            if let Ok(mut memo) = self.state.memo.lock() {
357	                memo.entry((info.id, cx.depth)).or_default().push(entry);
358	            }
359	            Ok(converted)
360	        })
361	    }
362	
363	    /// The entry for the type at this depth that holds inside the instantiations enclosing it, if there is one.
364	    fn recall(&self, id: u64, cx: &Cx) -> Option<Arc<Entry>> {
365	        let memo = self.state.memo.lock().ok()?;
366	        memo.get(&(id, cx.depth))?.iter().find(|entry| entry.holds_in(&cx.enclosing)).cloned()
367	    }
