369	    async fn uncached(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
370	        if info.is_error() {
371	            return Ok(unresolved_type(self.display(info.id).await?));
372	        }
373	        if let Some(simple) = simple(info) {
374	            return Ok(simple);
375	        }
376	        let flags = info.flags;
377	        if flags & flag::TYPE_PARAMETER != 0 {
378	            return self.type_parameter(info).await;
379	        }
380	        if flags & (flag::STRING_LITERAL | flag::NUMBER_LITERAL | flag::BIG_INT_LITERAL) != 0 {
381	            return self.literal(info).await;
382	        }
383	        if flags & flag::BOOLEAN_LITERAL != 0 {
384	            return Ok(PropType::BoolLiteral(self.boolean_value(info).await?));
385	        }
386	        if flags & flag::UNIQUE_ES_SYMBOL != 0 {
387	            let name = self.rpc.symbol_of_type(info.id).await?.map(|symbol| symbol.name);
388	            return Ok(match name {
389	                Some(name) => PropType::UniqueSymbol { name: name.into() },
390	                None => named(self.display(info.id).await?, Vec::new()),
391	            });
392	        }
393	        if flags & flag::TEMPLATE_LITERAL != 0 {
394	            return self.template(info, cx).await;
395	        }
396	        // `Uppercase<string>` and its siblings: a name, since there is no shape to expand.
397	        if flags & flag::STRING_MAPPING != 0 {
398	            return Ok(named(self.display(info.id).await?, Vec::new()));
399	        }
400	        // Types the checker could not resolve because a type parameter is still open.
401	        if flags & (flag::CONDITIONAL | flag::INDEXED_ACCESS | flag::INDEX | flag::SUBSTITUTION) != 0 {
402	            let text = self.display(info.id).await?;
403	            let reason = if flags & flag::CONDITIONAL != 0 {
404	                OpaqueReason::ConditionalType
405	            } else if flags & flag::INDEXED_ACCESS != 0 {
406	                OpaqueReason::IndexedAccess { expression: text.clone() }
407	            } else {
408	                OpaqueReason::UnsupportedExpression
409	            };
410	            return Ok(degraded_type(text, reason));
411	        }
412	        if flags & flag::UNION != 0 {
413	            return self.union(info, cx).await;
414	        }
415	        if flags & flag::INTERSECTION != 0 {
416	            return self.intersection(info, cx).await;
417	        }
418	        if flags & flag::OBJECT != 0 {
419	            return self.object(info, cx).await;
420	        }
421	        Ok(named(self.display(info.id).await?, Vec::new()))
422	    }
