476	    /// The declaration behind a symbol, asked once per symbol however many types refer to it.
477	    async fn origin_of(&self, symbol: &CompactSymbol, alias: bool, type_id: u64) -> Result<Option<Origin>, CallError> {
478	        let key = (alias, symbol.clone());
479	        if let Some(known) = self.state.origins.lock().ok().and_then(|origins| origins.get(&key).cloned()) {
480	            return Ok(known);
481	        }
482	        let found =
483	            if alias { self.rpc.alias_symbol(type_id).await? } else { self.rpc.symbol_of_type(type_id).await? };
484	        // `__type` and `__object` are the checker's names for a type that has none.
485	        let found = found.map(|symbol| Origin::of(&symbol, alias)).filter(|origin| !origin.name.starts_with("__"));
486	        if let Ok(mut origins) = self.state.origins.lock() {
487	            origins.insert(key, found.clone());
488	        }
489	        Ok(found)
490	    }
