492	    async fn type_parameter(&self, info: &TypeInfo) -> Result<PropType, CallError> {
493	        if info.is_this_type {
494	            return Ok(named("this".to_string(), Vec::new()));
495	        }
496	        let name = match self.rpc.symbol_of_type(info.id).await? {
497	            Some(symbol) => symbol.name,
498	            None => self.display(info.id).await?,
499	        };
