503	    async fn literal(&self, info: &TypeInfo) -> Result<PropType, CallError> {
504	        let flags = info.flags;
505	        let value = info.value.as_ref();
506	        let known = if flags & flag::BIG_INT_LITERAL != 0 {
507	            value.and_then(|value| value.as_str()).and_then(BigIntValue::parse).map(PropType::BigIntLiteral)
508	        } else if flags & flag::STRING_LITERAL != 0 {
509	            value.and_then(|value| value.as_str()).map(|text| PropType::StringLiteral(text.to_string()))
510	        } else {
511	            value.and_then(|value| value.as_f64()).map(PropType::NumberLiteral)
512	        };
513	        let Some(literal) = known else { return Ok(named(self.display(info.id).await?, Vec::new())) };
514	        if flags & flag::ENUM_LITERAL == 0 {
515	            return Ok(literal);
516	        }
517	        // A member of an enum is its value and keeps the enum's name.
518	        let Some(member) = self.rpc.symbol_of_type(info.id).await? else { return Ok(literal) };
519	        let Some(parent) = self.rpc.parent_of_symbol(&member.reference).await? else { return Ok(literal) };
520	        let value = match literal {
521	            PropType::StringLiteral(text) => EnumMemberValue::String(text),
522	            PropType::NumberLiteral(number) => EnumMemberValue::Number(number),
523	            other => return Ok(other),
524	        };
525	        Ok(PropType::EnumMember { enum_name: parent.name.into(), member: member.name.into(), value })
526	    }
