528	    /// The beta's responses carry neither `value` nor, in some builds, `intrinsicName` for `true` and `false`.
529	    async fn boolean_value(&self, info: &TypeInfo) -> Result<bool, CallError> {
530	        if let Some(name) = info.intrinsic_name.as_deref() {
531	            return Ok(name == "true");
532	        }
533	        if let Some(value) = info.value.as_ref().and_then(|value| value.as_bool()) {
534	            return Ok(value);
535	        }
536	        Ok(self.display(info.id).await? == "true")
537	    }
