539	    async fn template(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
540	        let origin = self.alias_origin(info).await?;
541	        let gate = self.enter(info, origin.as_ref(), cx, MAX_MEMBERS, || self.members_of(info)).await?;
542	        let (holes, inner) = match gate {
543	            Gate::Stop(stopped) => return Ok(stopped),
544	            Gate::Open { parts, inner } => (parts, inner),
545	        };
546	        let mut types = self.convert_all(&holes, &inner).await?.into_iter();
547	        let mut parts = Vec::new();
548	        for text in &info.texts {
549	            if !text.is_empty() {
550	                parts.push(TemplatePart::Text(text.clone()));
551	            }
552	            if let Some(hole) = types.next() {
553	                parts.push(TemplatePart::Type(hole));
554	            }
555	        }
556	        Ok(PropType::TemplateLiteral(parts))
557	    }
