605	    /// The one gate every descent into the parts of a type passes, before the parts are converted. It stops, in this
606	    /// order, a type that is an instantiation already being expanded around it (a back-reference to its declaration,
607	    /// whose arguments are the instantiation's), a type past [`MAX_DEPTH`], and a type whose `measure`d parts exceed the
608	    /// `limits`. `measure` fetches the parts and says how many there are; it is not called for a type stopped before.
609	    /// Otherwise the parts come back with the context to convert them in.
610	    async fn enter<T, F, Fut>(
611	        &self,
612	        info: &TypeInfo,
613	        origin: Option<&Origin>,
614	        cx: &Cx,
615	        limits: [usize; 2],
616	        measure: F,
617	    ) -> Result<Gate<T>, CallError>
618	    where
619	        T: Send,
620	        F: FnOnce() -> Fut + Send,
621	        Fut: Future<Output = Result<(T, usize), CallError>> + Send,
622	    {
623	        // The handle is the instantiation: `Box<string>` inside `Box<Box<string>>` is another type from the one around it.
624	        if let Some(origin) = origin
625	            && cx.encloses(info.id)
626	        {
627	            return Ok(Gate::Stop(self.recursive(info, origin, cx).await?));
628	        }
629	        if cx.depth >= MAX_DEPTH {
630	            return Ok(Gate::Stop(self.truncated(info, origin, TruncationLimit::Depth).await?));
631	        }
632	        let (parts, total) = measure().await?;
633	        if total > cx.limit(limits) {
634	            let limit = TruncationLimit::Members { total: to_u32(total) };
635	            return Ok(Gate::Stop(self.truncated(info, origin, limit).await?));
636	        }
637	        Ok(Gate::Open { parts, inner: cx.below(origin.map(|_| info.id)) })
638	    }
639	
640	    async fn union(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
641	        let origin = self.origin(info).await?;
642	        if let Some(terminal) = origin.as_ref().and_then(Origin::react_terminal) {
643	            return Ok(terminal);
644	        }
645	        // The width is checked below, after React's aliases flattened into the union are recognized: they are wide.
646	        let gate = self.enter(info, origin.as_ref(), cx, [usize::MAX; 2], || self.members_of(info)).await?;
647	        let (members, inner) = match gate {
648	            Gate::Stop(stopped) => return Ok(stopped),
649	            Gate::Open { parts, inner } => (parts, inner),
650	        };
651	        // `ReactNode | (() => void)` arrives with the alias flattened into its members: they are the terminal again.
652	        let over = members.len() > cx.limit(MAX_MEMBERS);
653	        let Some((terminal, absorbed)) = self.react_alias_members(&members, over).await? else {
654	            if over {
655	                let limit = TruncationLimit::Members { total: to_u32(members.len()) };
656	                return self.truncated(info, origin.as_ref(), limit).await;
657	            }
658	            return Ok(union_of(self.convert_all(&members, &inner).await?));
659	        };
660	        let kept: Vec<TypeInfo> = members
661	            .iter()
662	            .zip(&absorbed)
663	            .filter(|(_, absorbed)| !**absorbed)
664	            .map(|(member, _)| member.clone())
665	            .collect();
666	        if kept.len() + 1 > cx.limit(MAX_MEMBERS) {
667	            let limit = TruncationLimit::Members { total: to_u32(kept.len() + 1) };
668	            return self.truncated(info, origin.as_ref(), limit).await;
669	        }
670	        let mut converted = self.convert_all(&kept, &inner).await?;
671	        let first = absorbed.iter().position(|absorbed| *absorbed).unwrap_or_default();
672	        let before = absorbed.iter().take(first).filter(|absorbed| !**absorbed).count();
673	        converted.insert(before, terminal);
674	        Ok(union_of(converted))
675	    }
676	
677	    /// The members of a union that are a React alias the checker flattened into it, with the terminal they stand for,
678	    /// when the union holds all of that alias's members. `ReactNode | Fn` and `ElementType | undefined` arrive without
679	    /// the alias, so what is left to recognize it by is React's own declarations, never the printed text. `ElementType`
680	    /// is recognized only where the union is wider than the budget: below it the members are listed, which keeps the
681	    /// props of a constrained `ElementType<P>` in its component types' arguments, as it does at the top of a prop.
682	    async fn react_alias_members(
683	        &self,
684	        members: &[TypeInfo],
685	        over: bool,
686	    ) -> Result<Option<(PropType, Vec<bool>)>, CallError> {
687	        if let Some(absorbed) = self.react_node_members(members).await? {
688	            return Ok(Some((PropType::ReactNode, absorbed)));
689	        }
690	        if !over {
691	            return Ok(None);
692	        }
693	        Ok(self.element_type_members(members).await?.map(|absorbed| (PropType::ElementType, absorbed)))
694	    }
695	
696	    /// Which members of a union are those of React's `ElementType`: the tag names of `JSX.IntrinsicElements` as string
697	    /// literals and `ComponentType`'s two arms, `ComponentClass` and `FunctionComponent`. The tag names are many
698	    /// ([`MIN_INTRINSIC_TAGS`]), which keeps a union of a few tags and a component type the author's own. Only a literal
699	    /// that [`is_tag`] is taken: any other string literal is an alternative the author wrote beside `ElementType`, and
700	    /// the terminal does not stand for it.
701	    async fn element_type_members(&self, members: &[TypeInfo]) -> Result<Option<Vec<bool>>, CallError> {
702	        let tags = members.iter().filter(|member| is_tag(member)).count();
703	        if tags < MIN_INTRINSIC_TAGS {
704	            return Ok(None);
705	        }
706	        let (mut class, mut function) = (false, false);
707	        let mut absorbed = Vec::with_capacity(members.len());
708	        for member in members {
709	            let mut takes = is_tag(member);
710	            if member.flags & flag::OBJECT != 0
711	                && member.object_flags & (flag::OBJECT_CLASS | flag::OBJECT_INTERFACE | flag::OBJECT_REFERENCE) != 0
712	                && let Some(origin) = self.symbol_origin(member).await?
713	                && origin.in_react()
714	            {
715	                match origin.name.as_str() {
716	                    "ComponentClass" => (class, takes) = (true, true),
717	                    "FunctionComponent" => (function, takes) = (true, true),
