726	    /// Which members of a union are the members of React's `ReactNode`, when the union holds all of them. The union has
727	    /// `ReactElement`, `ReactPortal` and an `Iterable` of `ReactNode` (found by its argument's alias) and the primitives
728	    /// `ReactNode` lists. It then also takes the other members `ReactNode` has (`bigint`, `Promise<AwaitedReactNode>`),
729	    /// and leaves the rest. A union that has only some of them is the author's own and is expanded.
730	    async fn react_node_members(&self, members: &[TypeInfo]) -> Result<Option<Vec<bool>>, CallError> {
731	        let primitive = |flags: u64| flags & (flag::STRING | flag::NUMBER | flag::BOOLEAN | flag::BOOLEAN_LITERAL) != 0;
732	        let has = |flags: u64| members.iter().any(|member| member.flags & flags != 0);
733	        let listed = has(flag::STRING)
734	            && has(flag::NUMBER)
735	            && has(flag::BOOLEAN | flag::BOOLEAN_LITERAL)
736	            && has(flag::NULL)
737	            && has(flag::UNDEFINED);
738	        if !listed {
739	            return Ok(None);
740	        }
741	        let (mut element, mut portal, mut iterable) = (false, false, false);
742	        let mut absorbed = Vec::with_capacity(members.len());
743	        for member in members {
744	            let flags = member.flags;
745	            let takes = if primitive(flags) || flags & (flag::BIG_INT | flag::NULL | flag::UNDEFINED) != 0 {
746	                true
747	            } else if flags & flag::OBJECT != 0
748	                && member.object_flags & (flag::OBJECT_CLASS | flag::OBJECT_INTERFACE | flag::OBJECT_REFERENCE) != 0
749	                && let Some(origin) = self.symbol_origin(member).await?
750	            {
751	                let react = origin.in_react() && !origin.alias;
752	                let lib = origin.in_lib() && !origin.alias;
753	                if react && origin.name == "ReactElement" {
754	                    element = true;
755	                    true
756	                } else if react && origin.name == "ReactPortal" {
757	                    portal = true;
758	                    true
759	                } else if lib && origin.name == "Iterable" && self.argument_is_alias(member, "ReactNode").await? {
760	                    iterable = true;
761	                    true
762	                } else {
763	                    lib && origin.name == "Promise" && self.argument_is_alias(member, "AwaitedReactNode").await?
764	                }
765	            } else {
766	                false
767	            };
768	            absorbed.push(takes);
769	        }
770	        Ok((element && portal && iterable).then_some(absorbed))
771	    }
