812	    async fn object(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
813	        if info.is_tuple_type {
814	            return self.tuple(info, cx).await;
815	        }
816	        if info.object_flags & flag::OBJECT_REFERENCE != 0
817	            && let Some(own) = self.symbol_origin(info).await?
818	            && own.in_lib()
819	            && !own.alias
820	            && matches!(own.name.as_str(), "Array" | "ReadonlyArray")
821	        {
822	            return self.array(info, own.name == "ReadonlyArray", cx).await;
823	        }
824	        let origin = self.origin(info).await?;
825	        if let Some(terminal) = origin.as_ref().and_then(Origin::react_terminal) {
826	            return Ok(terminal);
827	        }
828	        let boundary = origin.as_ref().filter(|origin| origin.is_boundary());
829	        // A dependency's interface is a name unless it is callable; its properties are not asked for.
830	        if let Some(origin) = boundary
831	            && self.rpc.signatures(info.id, SignatureKind::Call).await?.is_empty()
832	        {
833	            return self.named_type(info, origin, cx).await;
834	        }
835	        // The width is not counted at the gate: only the members that are not the project's own are, below.
836	        let gate = self
837	            .enter(info, origin.as_ref(), cx, [usize::MAX; 2], || async {
838	                Ok((self.rpc.object_members(info.id).await?, 0))
839	            })
840	            .await?;
841	        let (members, inner) = match gate {
842	            Gate::Stop(stopped) => return Ok(stopped),
843	            Gate::Open { parts, inner } => (parts, inner),
844	        };
845	        if let Some(origin) = boundary
846	            && !members.properties.is_empty()
847	        {
848	            return self.named_type(info, origin, cx).await;
849	        }
850	        let outside = members.properties.iter().filter(|property| !is_own(property)).count();
851	        if outside > cx.limit(MAX_FIELDS) {
852	            return self.over_budget(info, origin.as_ref(), members, cx, &inner).await;
853	        }
854	        let ObjectMembers { calls, constructs, properties, indexes } = members;
855	
856	        // Which of a signature's parameters are optional is read from the printed type here, and nowhere else.
857	        let Some(markers) = self.printed_markers(info.id, &calls, &constructs).await? else {
858	            return self.unreadable_signatures(info.id).await;
859	        };
860	        let mut signatures = Vec::with_capacity(calls.len() + constructs.len());
861	        for (kind, group, printed) in
862	            [(Kind::Call, &calls, &markers.calls), (Kind::Construct, &constructs, &markers.constructs)]
863	        {
864	            for (index, signature) in group.iter().enumerate() {
865	                let printed = printed.get(index).map(Vec::as_slice);
866	                let Some((type_params, params, return_type)) = self.signature_parts(signature, printed, &inner).await?
867	                else {
868	                    return self.unreadable_signatures(info.id).await;
869	                };
870	                signatures.push(CallSignature { kind, type_params, params, return_type });
871	            }
872	        }
873	        if signatures.len() == 1 && calls.len() == 1 && properties.is_empty() && indexes.is_empty() {
874	            let CallSignature { type_params, params, return_type, .. } = signatures.swap_remove(0);
875	            return Ok(PropType::Function { type_params, params, return_type: Box::new(return_type) });
876	        }
877	        let fields = self.fields(&properties, &indexes, &inner).await?;
878	        if signatures.is_empty() {
879	            return Ok(PropType::Object(fields));
880	        }
881	        Ok(PropType::Callable { signatures, fields })
882	    }
