884	    /// An object with more members from outside the project (inherited from a dependency or the lib) than the budget
885	    /// lists. What the project declared itself is never cut. The rest stands as what it is named through: the utility
886	    /// wrapper that built the type (`Omit<HTMLAttributes<HTMLDivElement>, "color">`), or the base types of the interface
887	    /// or class that inherits it. When neither can be named, the rest is a [`PropType::Truncated`] with the real count.
888	    async fn over_budget(
889	        &self,
890	        info: &TypeInfo,
891	        origin: Option<&Origin>,
892	        members: ObjectMembers,
893	        cx: &Cx,
894	        inner: &Cx,
895	    ) -> Result<PropType, CallError> {
896	        let ObjectMembers { calls, constructs, properties, indexes } = members;
897	        let cut =
898	            TruncationLimit::Members { total: to_u32(properties.iter().filter(|property| !is_own(property)).count()) };
899	        // A type with signatures is a function with properties: its shape is not a set of fields to split.
900	        if !calls.is_empty() || !constructs.is_empty() {
901	            return self.truncated(info, origin, cut).await;
902	        }
903	        if let Some(origin) = origin
904	            && origin.alias
905	            && let Some(wrapper) = self.wrapper(info, origin, cx).await?
906	        {
907	            return Ok(wrapper);
908	        }
909	        // The declaration of a class or interface has base types; an instantiation of a generic one (`Box<string>`, only a
910	        // reference) does not state them in terms of its arguments, so it is cut.
911	        let layers = if origin.is_some_and(|origin| !origin.alias) && states_bases(info) {
912	            self.base_layers(info, cx).await?
913	        } else {
914	            None
915	        };
916	        let own: Vec<SymbolInfo> = properties.into_iter().filter(is_own).collect();
917	        let mut parts = Vec::new();
918	        if !own.is_empty() || !indexes.is_empty() {
919	            parts.push(PropType::Object(self.fields(&own, &indexes, inner).await?));
920	        }
921	        match layers {
922	            Some(layers) => parts.extend(layers),
923	            None => parts.push(self.truncated(info, origin, cut).await?),
924	        }
925	        Ok(if parts.len() == 1 { parts.swap_remove(0) } else { PropType::Intersection(parts) })
926	    }
