928	    /// What a type declared as `interface A extends B, C` stands on: each base type named (see [`Self::layer`]), a base
929	    /// the project declares seen through to its own bases (its members are the project's own and are listed). `None`
930	    /// when a base is neither.
931	    async fn base_layers(&self, info: &TypeInfo, cx: &Cx) -> Result<Option<Vec<PropType>>, CallError> {
932	        let mut layers: Vec<PropType> = Vec::new();
933	        let mut pending: Vec<TypeInfo> = self.rpc.base_types(info.id).await?;
934	        pending.reverse();
935	        while let Some(base) = pending.pop() {
936	            if let Some(layer) = self.layer(&base, cx).await? {
937	                if !layers.contains(&layer) {
938	                    layers.push(layer);
939	                }
940	                continue;
941	            }
942	            // A base declared in the project: its members are already among the type's own, and what it inherits is
943	            // seen through to its own bases. An instantiation of a generic one does not state them, so what it
944	            // inherits would be missing from the answer: the type is cut instead, with its count.
945	            let declared_here = match self.origin(&base).await? {
946	                Some(origin) => !origin.alias && !origin.in_dependency() && !origin.in_lib(),
947	                None => false,
948	            };
949	            if !declared_here || !states_bases(&base) {
950	                return Ok(None);
951	            }
952	            let mut inherited = self.rpc.base_types(base.id).await?;
953	            inherited.reverse();
954	            pending.extend(inherited);
955	        }
956	        // Members came from somewhere: bases that account for none of them are not an answer.
957	        Ok((!layers.is_empty()).then_some(layers))
958	    }
