1106	        let mut fields = Vec::with_capacity(properties.len() + indexes.len());
1107	        for ((property, prop_type), readonly) in properties.iter().zip(converted).zip(readonly) {
1108	            let required = property.flags & flag::SYMBOL_OPTIONAL == 0;
1109	            let prop_type = without_undefined(prop_type, !required);
1110	            let mut field = ObjectField::new(property_name(&property.name), prop_type, required, String::new());
1111	            field.readonly = readonly;
