1164	            return Ok(None);
1165	        }
1166	        let references: Vec<_> = parameters.iter().map(|parameter| &parameter.reference).collect();
1167	        let types = if references.is_empty() { Vec::new() } else { self.rpc.types_of_symbols(&references).await? };
1168	        let converted = self.convert_all(&types, cx).await?;
1169	        let mut params = Vec::with_capacity(parameters.len());
1170	        for (index, (parameter, param_type)) in parameters.iter().zip(converted).enumerate() {
1171	            let marker = markers.and_then(|markers| markers.get(index)).copied().unwrap_or_default();
1172	            let rest = marker.rest || (has_rest && index + 1 == parameters.len());
1173	            let optional = marker.optional && !rest;
1174	            let param_type = without_undefined(param_type, optional);
1175	            // A destructured parameter has no name of its own; the checker calls it `__0`.
1176	            let name = (!is_destructured(&parameter.name)).then(|| parameter.name.clone());
1177	            params.push(FunctionParam { name, param_type, optional, rest });
1178	        }
1179	        let return_info = self.rpc.return_type(signature.id).await?;
1180	        let return_type = self.convert(&return_info, cx).await?;
1181	        let mut type_params = Vec::new();
1182	        if !signature.type_parameters.is_empty() {
1183	            for parameter in self.rpc.type_parameters(signature.id).await? {
1184	                match self.rpc.symbol_of_type(parameter.id).await? {
1185	                    Some(symbol) => type_params.push(symbol.name),
1186	                    None => type_params.push(self.display(parameter.id).await?),
1187	                }
1188	            }
1189	        }
1190	        Ok(Some((type_params, params, return_type)))
1191	    }
1192	}
1193	
1194	/// The checker keys a property named by a symbol `__@<name>@<symbol id>`; the source writes `[Symbol.iterator]` or
1195	/// `[brand]`. The id is the checker's and does not belong in an answer.
1196	fn property_name(name: &str) -> String {
1197	    const WELL_KNOWN: [&str; 15] = [
1198	        "iterator",
1199	        "asyncIterator",
1200	        "hasInstance",
1201	        "isConcatSpreadable",
1202	        "match",
1203	        "matchAll",
1204	        "replace",
1205	        "search",
1206	        "species",
1207	        "split",
1208	        "toPrimitive",
1209	        "toStringTag",
1210	        "unscopables",
1211	        "dispose",
1212	        "asyncDispose",
1213	    ];
1214	    let Some((symbol, _id)) = name.strip_prefix("__@").and_then(|rest| rest.rsplit_once('@')) else {
1215	        return name.to_string();
1216	    };
1217	    if WELL_KNOWN.contains(&symbol) { format!("[Symbol.{symbol}]") } else { format!("[{symbol}]") }
1218	}
1219	
1220	fn is_destructured(name: &str) -> bool {
1221	    name.strip_prefix("__").is_some_and(|rest| !rest.is_empty() && rest.chars().all(|c| c.is_ascii_digit()))
1222	}
1223	
1224	fn to_u32(count: usize) -> u32 {
1225	    u32::try_from(count).unwrap_or(u32::MAX)
1226	}
1227	
1228	fn named(name: String, args: Vec<PropType>) -> PropType {
1229	    PropType::Named { name: name.into(), args }
1230	}
1231	
1232	/// The types whose conversion needs nothing but their flags.
1233	fn simple(info: &TypeInfo) -> Option<PropType> {
1234	    let flags = info.flags;
1235	    // `boolean` is the union `false | true` and carries both flags.
1236	    if flags & flag::BOOLEAN != 0 {
1237	        return Some(PropType::Boolean);
1238	    }
1239	    let known = [
1240	        (flag::ANY, PropType::Any),
1241	        (flag::UNKNOWN, PropType::Unknown),
1242	        (flag::UNDEFINED, PropType::Undefined),
1243	        (flag::NULL, PropType::Null),
1244	        (flag::VOID, PropType::Void),
1245	        (flag::NEVER, PropType::Never),
1246	        (flag::STRING, PropType::String),
1247	        (flag::NUMBER, PropType::Number),
1248	        (flag::BIG_INT, named("bigint".to_string(), Vec::new())),
1249	        (flag::ES_SYMBOL, named("symbol".to_string(), Vec::new())),
1250	        (flag::NON_PRIMITIVE, named("object".to_string(), Vec::new())),
1251	    ];
1252	    known.into_iter().find(|(bit, _)| flags & bit != 0).map(|(_, converted)| converted)
1253	}
1254	
1255	/// A union of converted members: `false | true` is `boolean`, a union inside a union is flattened, a repeated member
1256	/// is kept once, and a union of one is that member.
1257	fn union_of(converted: Vec<PropType>) -> PropType {
1258	    let mut flat = Vec::with_capacity(converted.len());
1259	    for member in converted {
1260	        match member {
1261	            PropType::Union(inner) => flat.extend(inner),
1262	            other => flat.push(other),
1263	        }
1264	    }
1265	    let both_booleans = flat.contains(&PropType::BoolLiteral(true)) && flat.contains(&PropType::BoolLiteral(false));
1266	    let mut members: Vec<PropType> = Vec::with_capacity(flat.len());
1267	    for member in flat {
1268	        let member = match member {
1269	            PropType::BoolLiteral(_) if both_booleans => PropType::Boolean,
1270	            other => other,
1271	        };
1272	        if !members.contains(&member) {
1273	            members.push(member);
1274	        }
1275	    }
1276	    if members.len() == 1 { members.swap_remove(0) } else { PropType::Union(members) }
1277	}
1278	
1279	/// An optional prop's type includes `undefined`; react-docgen-typescript drops it, as does the structural result.
1280	pub(crate) fn without_undefined(prop_type: PropType, optional: bool) -> PropType {
1281	    match prop_type {
1282	        PropType::Union(members) if optional => {
1283	            let mut kept: Vec<PropType> = members.into_iter().filter(|m| *m != PropType::Undefined).collect();
1284	            if kept.len() == 1 { kept.swap_remove(0) } else { PropType::Union(kept) }
1285	        }
1286	        other => other,
1287	    }
1288	}
1289

