210	    pub(crate) const INDEX: u64 = 2097152;
211	    pub(crate) const TEMPLATE_LITERAL: u64 = 4194304;
212	    pub(crate) const STRING_MAPPING: u64 = 8388608;
213	    pub(crate) const SUBSTITUTION: u64 = 16777216;
214	    pub(crate) const INDEXED_ACCESS: u64 = 33554432;
215	    pub(crate) const CONDITIONAL: u64 = 67108864;
216	    pub(crate) const UNION: u64 = 134217728;
217	    pub(crate) const INTERSECTION: u64 = 268435456;
218	    pub(crate) const SYMBOL_ALIAS: u64 = 2097152;
