220	    /// `SignatureFlags.HasRestParameter`: the signature's last parameter is a rest parameter. The beta sets it for
221	    /// `(...args: T[]) => R` and for `(a?: A, ...rest: B[]) => R`, and leaves every other signature at 0.
222	    pub(crate) const SIGNATURE_HAS_REST_PARAMETER: u64 = 1;
223	    /// `ObjectFlags`: a class or interface type, an instantiation of one (a reference), a tuple, a mapped type.
224	    pub(crate) const OBJECT_CLASS: u64 = 1;
