228	    /// `AllowUniqueESSymbolType` (the last two are what the checker uses when no flags are given) and `InTypeAlias`.
229	    pub(crate) const PRINT_EXPANDED: u64 = 1 | 16384 | 1_048_576 | 8_388_608;
230	    /// `TupleElementFlags`.
231	    pub(crate) const ELEMENT_OPTIONAL: u64 = 2;
