236	tokio::task_local! {
237	    /// The requests the component being answered has sent, so a debug line can say what each one cost.
238	    pub(crate) static REQUESTS: std::sync::Arc<std::sync::atomic::AtomicU64>;
239	}
240	
241	/// One `tsc --api` session bound to a snapshot and project.
242	pub(crate) struct Rpc {
243	    client: Client,
244	    deadline: Duration,
245	    snapshot: u64,
246	    project: String,
247	    /// Every call and its answer, when the caller asked to record a replay fixture.
248	    recording: Option<Mutex<Vec<Value>>>,
249	    calls: Mutex<BTreeMap<String, u64>>,
250	}
251	
252	impl Rpc {
253	    pub(crate) async fn open(
254	        client: Client,
255	        deadline: Duration,
256	        tsconfig: Option<&str>,
257	        root_files: &[String],
258	        record: bool,
259	    ) -> Result<Rpc, CallError> {
260	        let options = Rpc::prepare(&client, deadline, tsconfig).await?;
261	        Rpc::open_with(client, deadline, &options, root_files, record).await
262	    }
263	
264	    /// Initializes the `tsc` session and reads the compiler options, once per process. The beta panics on
265	    /// string-valued enum options such as `target: "es2022"`, so options come from `parseConfigFile`, which yields
266	    /// numeric ones.
267	    pub(crate) async fn prepare(
268	        client: &Client,
269	        deadline: Duration,
270	        tsconfig: Option<&str>,
271	    ) -> Result<Value, CallError> {
272	        let rpc = Rpc {
273	            client: client.clone(),
274	            deadline,
275	            snapshot: 0,
276	            project: String::new(),
277	            recording: None,
278	            calls: Mutex::new(BTreeMap::new()),
279	        };
280	        rpc.call("initialize", Value::Null).await?;
281	        Ok(match tsconfig {
282	            Some(file) => {
283	                let parsed = rpc.call("parseConfigFile", json!({ "file": file })).await?;
284	                parsed.get("options").cloned().unwrap_or_else(default_options)
285	            }
286	            None => default_options(),
287	        })
288	    }
289	
290	    /// A snapshot over `root_files` in a session [`Rpc::prepare`] already initialized.
291	    pub(crate) async fn open_with(
292	        client: Client,
293	        deadline: Duration,
294	        options: &Value,
295	        root_files: &[String],
296	        record: bool,
297	    ) -> Result<Rpc, CallError> {
298	        let mut rpc = Rpc {
299	            client,
300	            deadline,
301	            snapshot: 0,
302	            project: String::new(),
303	            recording: record.then(|| Mutex::new(Vec::new())),
304	            calls: Mutex::new(BTreeMap::new()),
305	        };
306	        let created = rpc
307	            .call(
308	                "createSnapshot",
309	                json!({ "createPrograms": [{ "rootFiles": root_files, "compilerOptions": options }] }),
310	            )
311	            .await?;
312	        let response: SnapshotResponse = decode(created)?;
313	        let project = response
314	            .projects
315	            .into_iter()
316	            .next()
317	            .ok_or_else(|| CallError::Rejected("createSnapshot returned no project".to_string()))?;
318	        rpc.snapshot = response.snapshot;
319	        rpc.project = project.id;
320	        Ok(rpc)
321	    }
322	
323	    pub(crate) async fn release(&self) {
324	        self.call("release", json!({ "snapshot": self.snapshot })).await.ok();
325	    }
326	
327	    /// The recorded calls as a JSON array, or `None` when recording was off.
328	    pub(crate) fn recording(&self) -> Option<Value> {
329	        let log = self.recording.as_ref()?.lock().ok()?;
330	        Some(Value::Array(log.clone()))
331	    }
332	
333	    /// Requests sent so far, by method.
334	    pub(crate) fn calls(&self) -> BTreeMap<String, u64> {
335	        self.calls.lock().map(|calls| calls.clone()).unwrap_or_default()
336	    }
337	
338	    async fn call(&self, method: &str, params: Value) -> Result<Value, CallError> {
339	        if let Ok(mut calls) = self.calls.lock() {
340	            *calls.entry(method.to_string()).or_default() += 1;
341	        }
342	        REQUESTS.try_with(|count| count.fetch_add(1, std::sync::atomic::Ordering::Relaxed)).ok();
343	        let answer = self.client.request(method, params.clone(), self.deadline).await.map_err(classify)?;
344	        if let Some(log) = &self.recording
345	            && let Ok(mut log) = log.lock()
346	        {
347	            log.push(json!({ "method": method, "params": params, "result": answer.value }));
348	        }
349	        Ok(answer.value)
350	    }
351	
352	    async fn scoped<T: DeserializeOwned>(&self, method: &str, extra: Value) -> Result<T, CallError> {
353	        let mut params = json!({ "snapshot": self.snapshot, "project": self.project });
354	        if let (Some(base), Value::Object(extra)) = (params.as_object_mut(), extra) {
355	            base.extend(extra);
356	        }
357	        decode(self.call(method, params).await?)
358	    }
359	
360	    pub(crate) async fn source_file_symbol(&self, file: &str) -> Result<Option<SymbolInfo>, CallError> {
361	        self.scoped("getSymbolOfSourceFile", json!({ "file": file })).await
362	    }
363	
364	    pub(crate) async fn exports_of_module(&self, module: &Value) -> Result<Vec<SymbolInfo>, CallError> {
365	        self.scoped("getExportsOfModule", json!({ "symbol": module })).await
366	    }
367	
368	    /// Only for symbols flagged `Alias`: the beta panics on a plain `default` export.
369	    pub(crate) async fn aliased_symbol(&self, symbol: &Value) -> Result<SymbolInfo, CallError> {
370	        self.scoped("getAliasedSymbol", json!({ "symbol": symbol })).await
371	    }
372	
373	    pub(crate) async fn type_of_symbol(&self, symbol: &Value) -> Result<TypeInfo, CallError> {
374	        self.scoped("getTypeOfSymbol", json!({ "symbol": symbol })).await
375	    }
376	
377	    pub(crate) async fn types_of_symbols(&self, symbols: &[&Value]) -> Result<Vec<TypeInfo>, CallError> {
378	        self.scoped("getTypesOfSymbols", json!({ "symbols": symbols })).await
379	    }
380	
381	    /// The call signatures of a type, or with `SignatureKind::Construct` its construct signatures.
382	    pub(crate) async fn signatures(&self, type_id: u64, kind: SignatureKind) -> Result<Vec<SignatureInfo>, CallError> {
383	        self.scoped("getSignaturesOfType", json!({ "type": type_id, "kind": kind as u8 })).await
384	    }
385	
386	    pub(crate) async fn type_parameters(&self, signature: u64) -> Result<Vec<TypeInfo>, CallError> {
387	        self.scoped("getTypeParametersOfSignature", json!({ "objectId": signature })).await
388	    }
389	
390	    /// The symbol that declares a type: the interface, class, enum member or unique symbol behind it.
391	    pub(crate) async fn symbol_of_type(&self, type_id: u64) -> Result<Option<SymbolInfo>, CallError> {
392	        self.scoped("getSymbolOfType", json!({ "objectId": type_id })).await
393	    }
394	
395	    /// The types a class or interface extends, instantiated as it names them (`Omit<HTMLAttributes<HTMLDivElement>, "color">`);
396	    /// none for a type that is not a class or interface.
397	    pub(crate) async fn base_types(&self, type_id: u64) -> Result<Vec<TypeInfo>, CallError> {
398	        let bases: Option<Vec<TypeInfo>> = self.scoped("getBaseTypes", json!({ "type": type_id })).await?;
399	        Ok(bases.unwrap_or_default())
400	    }
401	
402	    pub(crate) async fn alias_type_arguments(&self, type_id: u64) -> Result<Vec<TypeInfo>, CallError> {
403	        self.scoped("getAliasTypeArgumentsOfType", json!({ "objectId": type_id })).await
404	    }
405	
406	    /// The generic type a reference instantiates; for a tuple reference, the tuple type that holds its element flags.
407	    pub(crate) async fn target_of_type(&self, type_id: u64) -> Result<TypeInfo, CallError> {
408	        self.scoped("getTargetOfType", json!({ "objectId": type_id })).await
409	    }
410	
411	    pub(crate) async fn parent_of_symbol(&self, symbol: &Value) -> Result<Option<SymbolInfo>, CallError> {
412	        self.scoped("getParentOfSymbolForChecker", json!({ "symbol": symbol })).await
413	    }
414	
415	    /// Whether each property is declared `readonly`, in one round trip.
416	    pub(crate) async fn readonly_symbols(&self, symbols: &[&Value]) -> Result<Vec<bool>, CallError> {
417	        let requests = symbols.iter().map(|symbol| ("isReadonlySymbol", json!({ "symbol": symbol }))).collect();
418	        self.batch(requests).await?.into_iter().map(decode).collect()
419	    }
420	
421	    /// Several requests in one round trip. A request the checker rejects fails the batch: nothing here asks for one
422	    /// that may legitimately fail.
423	    pub(crate) async fn batch(&self, requests: Vec<(&str, Value)>) -> Result<Vec<Value>, CallError> {
424	        let wanted = requests.len();
425	        let scoped: Vec<Value> = requests
426	            .into_iter()
427	            .map(|(method, mut params)| {
428	                if let Value::Object(map) = &mut params {
429	                    map.insert("snapshot".to_string(), json!(self.snapshot));
430	                    map.insert("project".to_string(), json!(self.project));
431	                }
432	                json!({ "method": method, "params": params })
433	            })
434	            .collect();
435	        let mut answers = Vec::with_capacity(wanted);
436	        let mut token: Option<String> = None;
437	        loop {
438	            let mut params = json!({ "requests": scoped });
439	            if let (Some(token), Some(map)) = (&token, params.as_object_mut()) {
440	                map.insert("continuationToken".to_string(), json!(token));
441	            }
442	            let page: BatchPage = decode(self.call("batchRequests", params).await?)?;
443	            for response in page.responses {
444	                if let Some(error) = response.error {
445	                    return Err(CallError::Rejected(error));
446	                }
447	                answers.push(response.result);
448	            }
449	            match page.continuation_token {
450	                Some(next) => token = Some(next),
451	                None => break,
452	            }
453	        }
454	        if answers.len() != wanted {
455	            return Err(CallError::Rejected(format!("a batch of {wanted} requests got {} answers", answers.len())));
456	        }
457	        Ok(answers)
458	    }
459	
460	    pub(crate) async fn parameters(&self, signature: u64) -> Result<Vec<SymbolInfo>, CallError> {
461	        self.scoped("getParametersOfSignature", json!({ "objectId": signature })).await
462	    }
463	
464	    pub(crate) async fn return_type(&self, signature: u64) -> Result<TypeInfo, CallError> {
465	        self.scoped("getReturnTypeOfSignature", json!({ "objectId": signature })).await
466	    }
467	
468	    pub(crate) async fn properties(&self, type_id: u64) -> Result<Vec<SymbolInfo>, CallError> {
469	        self.scoped("getPropertiesOfType", json!({ "type": type_id })).await
470	    }
471	
472	    pub(crate) async fn members(&self, type_id: u64) -> Result<Vec<TypeInfo>, CallError> {
473	        self.scoped("getTypesOfType", json!({ "objectId": type_id })).await
474	    }
475	
476	    pub(crate) async fn type_arguments(&self, type_id: u64) -> Result<Vec<TypeInfo>, CallError> {
477	        self.scoped("getTypeArguments", json!({ "type": type_id })).await
478	    }
479	
480	    /// The call and construct signatures, the properties and the index signatures of a type, in one round trip.
481	    pub(crate) async fn object_members(&self, type_id: u64) -> Result<ObjectMembers, CallError> {
482	        let requests = vec![
483	            ("getSignaturesOfType", json!({ "type": type_id, "kind": SignatureKind::Call as u8 })),
484	            ("getSignaturesOfType", json!({ "type": type_id, "kind": SignatureKind::Construct as u8 })),
485	            ("getPropertiesOfType", json!({ "type": type_id })),
486	            ("getIndexInfosOfType", json!({ "type": type_id })),
487	        ];
488	        let mut answers = self.batch(requests).await?.into_iter();
489	        let mut next = || answers.next().ok_or_else(|| CallError::Rejected("a short batch".to_string()));
490	        Ok(ObjectMembers {
491	            calls: decode(next()?)?,
492	            constructs: decode(next()?)?,
493	            properties: decode(next()?)?,
494	            indexes: decode(next()?)?,
495	        })
496	    }
497	
498	    pub(crate) async fn alias_symbol(&self, type_id: u64) -> Result<Option<SymbolInfo>, CallError> {
499	        self.scoped("getAliasSymbolOfType", json!({ "objectId": type_id })).await
500	    }
501	
502	    pub(crate) async fn type_to_string(&self, type_id: u64) -> Result<String, CallError> {
503	        self.scoped("typeToString", json!({ "type": type_id })).await
504	    }
505	
506	    /// The type as written inside a type alias declaration, and never cut short: an alias at the top is printed as what
507	    /// it stands for (`(value?: string) => void`, not `Handler`), and a long type is printed to its end.
508	    pub(crate) async fn type_to_string_expanded(&self, type_id: u64) -> Result<String, CallError> {
509	        self.scoped("typeToString", json!({ "type": type_id, "flags": flag::PRINT_EXPANDED })).await
510	    }
511	
512	    pub(crate) async fn documentation(&self, symbol: &Value) -> Result<String, CallError> {
513	        self.scoped("getDocumentationComment", json!({ "symbol": symbol })).await
514	    }
515	}
516	
517	fn default_options() -> Value {
518	    // Numeric enum values: JSX preserve, ESNext modules, bundler resolution, ES2022.
519	    json!({ "jsx": 1, "module": 99, "moduleResolution": 100, "target": 9, "strict": true, "skipLibCheck": true, "noEmit": true })
520	}
521	
