1	//! Typed calls over one `tsc --api` session. Wire shapes are the ones the official 7.1 client sends (traced against
2	//! `7.1.0-beta`); a method this module does not name is not used.
3	
4	use std::collections::BTreeMap;
5	use std::sync::Mutex;
6	use std::time::Duration;
7	
8	use caliper_docgen_tsc_client::{Client, TscClientError};
9	use serde::Deserialize;
10	use serde::de::DeserializeOwned;
11	use serde_json::{Value, json};
12	
13	/// Why a call failed, split by whether the rest of the run can go on.
14	#[derive(Debug)]
15	pub(crate) enum CallError {
16	    /// The session is gone or stuck: every later call would fail the same way.
17	    Fatal(String),
18	    /// The checker rejected this one call; other components may still resolve.
19	    Rejected(String),
20	}
21	
22	impl std::fmt::Display for CallError {
23	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
24	        match self {
25	            CallError::Fatal(message) | CallError::Rejected(message) => f.write_str(message),
26	        }
27	    }
28	}
29	
30	fn classify(error: TscClientError) -> CallError {
31	    match error {
32	        TscClientError::RpcError { message, .. } => CallError::Rejected(message),
33	        other => CallError::Fatal(other.to_string()),
34	    }
35	}
36	
37	#[derive(Debug, Clone, Deserialize)]
38	#[serde(rename_all = "camelCase")]
39	pub(crate) struct SymbolInfo {
40	    /// The full reference the checker wants back to name this symbol; opaque to us.
41	    pub reference: Value,
42	    /// The name the source writes: the checker's escaped name with the escaping removed (see
43	    /// [`unescape_leading_underscores`]).
44	    #[serde(deserialize_with = "unescaped_name")]
45	    pub name: String,
46	    pub flags: u64,
47	    #[serde(default)]
48	    pub declarations: Vec<String>,
49	}
50	
51	/// A symbol as another response embeds it: the id, and the node id of the file that owns it. The full symbol is one
52	/// call away (`getSymbolOfType`, `getAliasSymbolOfType`).
53	#[derive(Debug, Clone, PartialEq, Eq, Hash, Deserialize)]
54	pub(crate) struct CompactSymbol {
55	    pub id: u64,
56	    #[serde(default)]
57	    pub file: Option<String>,
58	}
59	
60	/// The checker keeps a symbol's name in an escaped form: a name that starts with two underscores gets a third
61	/// (`escapeLeadingUnderscores`), so that it cannot collide with its own internal names such as `__call`. The source
62	/// writes `__size`, the checker answers `___size`. A name with fewer than three leading underscores is unchanged, and
63	/// so are the internal names, which start with exactly two.
64	pub(crate) fn unescape_leading_underscores(name: &str) -> &str {
65	    if name.starts_with("___") { name.strip_prefix('_').unwrap_or(name) } else { name }
66	}
67	
68	fn unescaped_name<'de, D: serde::Deserializer<'de>>(deserializer: D) -> Result<String, D::Error> {
69	    let name = String::deserialize(deserializer)?;
70	    Ok(unescape_leading_underscores(&name).to_string())
71	}
72	
73	#[derive(Debug, Clone, Deserialize)]
74	#[serde(rename_all = "camelCase")]
75	pub(crate) struct TypeInfo {
76	    pub id: u64,
77	    pub flags: u64,
78	    #[serde(default)]
79	    pub object_flags: u64,
80	    #[serde(default)]
81	    pub value: Option<Value>,
82	    #[serde(default)]
83	    pub is_tuple_type: bool,
84	    /// The checker's name for an intrinsic type (`"any"`, `"string"`, `"error"`). It alone tells a written `any` from
85	    /// the error type of an unresolved name: both carry the `Any` flag, and the error type has an id per site.
86	    #[serde(default)]
87	    pub intrinsic_name: Option<String>,
88	    /// `TupleElementFlags` of a tuple type's elements: required 1, optional 2, rest 4, variadic 8.
89	    #[serde(default)]
90	    pub element_flags: Vec<u64>,
91	    /// A tuple type written `readonly [...]`.
92	    #[serde(default)]
93	    pub readonly: bool,
94	    /// One declaration handle per element of a tuple whose elements are labeled, `[head: string]`; empty otherwise.
95	    #[serde(default)]
96	    pub labeled_element_declarations: Vec<String>,
97	    /// The text pieces of a template literal type, around its holes.
98	    #[serde(default)]
99	    pub texts: Vec<String>,
100	    /// The `this` type of a class or interface, which the checker also appends to a reference's type arguments.
101	    #[serde(default)]
102	    pub is_this_type: bool,
103	    /// The symbol that declares an object type; absent for primitives and unions.
104	    #[serde(default)]
105	    pub symbol: Option<CompactSymbol>,
106	    /// The alias this type was written through, `Size` in `type Size = "sm" | "lg"`.
107	    #[serde(default)]
108	    pub alias_symbol: Option<CompactSymbol>,
109	    /// Ids of the alias's type arguments; `Rpc::alias_type_arguments` fetches them.
110	    #[serde(default)]
111	    pub alias_type_arguments: Vec<u64>,
112	}
113	
114	impl TypeInfo {
115	    /// The checker's error type: what a name that does not resolve is typed as.
116	    pub(crate) fn is_error(&self) -> bool {
117	        self.flags & flag::ANY != 0 && self.intrinsic_name.as_deref() == Some("error")
118	    }
119	}
120	
121	#[derive(Debug, Clone, Deserialize)]
122	#[serde(rename_all = "camelCase")]
123	pub(crate) struct SignatureInfo {
124	    pub id: u64,
125	    /// `SignatureFlags`; see [`flag::SIGNATURE_HAS_REST_PARAMETER`].
126	    #[serde(default)]
127	    pub flags: u64,
128	    /// The signature's own type parameters (ids; `Rpc::type_parameters` fetches them).
129	    #[serde(default)]
130	    pub type_parameters: Vec<u64>,
131	    /// One entry per declared parameter, `this` excluded; `Rpc::parameters` fetches them.
132	    #[serde(default)]
133	    pub parameters: Vec<serde::de::IgnoredAny>,
134	}
135	
136	/// What an object type holds, as one batch answers it.
137	pub(crate) struct ObjectMembers {
138	    pub calls: Vec<SignatureInfo>,
139	    pub constructs: Vec<SignatureInfo>,
140	    pub properties: Vec<SymbolInfo>,
141	    pub indexes: Vec<IndexInfo>,
142	}
143	
144	/// One index signature of an object type, `[key: string]: T`.
145	#[derive(Debug, Clone, Deserialize)]
146	#[serde(rename_all = "camelCase")]
147	pub(crate) struct IndexInfo {
148	    pub key_type: TypeInfo,
149	    pub value_type: TypeInfo,
150	    #[serde(default)]
151	    pub is_readonly: bool,
152	}
153	
154	/// `SignatureKind` as the checker's `getSignaturesOfType` takes it.
155	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
156	#[repr(u8)]
157	pub(crate) enum SignatureKind {
158	    Call = 0,
159	    Construct = 1,
160	}
