241	/// One `tsc --api` session bound to a snapshot and project.
242	pub(crate) struct Rpc {
243	    client: Client,
244	    deadline: Duration,
245	    snapshot: u64,
246	    project: String,
247	    /// Every call and its answer, when the caller asked to record a replay fixture.
248	    recording: Option<Mutex<Vec<Value>>>,
249	    calls: Mutex<BTreeMap<String, u64>>,
250	}
