252	impl Rpc {
253	    pub(crate) async fn open(
254	        client: Client,
255	        deadline: Duration,
256	        tsconfig: Option<&str>,
257	        root_files: &[String],
258	        record: bool,
259	    ) -> Result<Rpc, CallError> {
260	        let options = Rpc::prepare(&client, deadline, tsconfig).await?;
261	        Rpc::open_with(client, deadline, &options, root_files, record).await
262	    }
263	
264	    /// Initializes the `tsc` session and reads the compiler options, once per process. The beta panics on
265	    /// string-valued enum options such as `target: "es2022"`, so options come from `parseConfigFile`, which yields
266	    /// numeric ones.
267	    pub(crate) async fn prepare(
268	        client: &Client,
269	        deadline: Duration,
270	        tsconfig: Option<&str>,
271	    ) -> Result<Value, CallError> {
272	        let rpc = Rpc {
273	            client: client.clone(),
274	            deadline,
275	            snapshot: 0,
276	            project: String::new(),
277	            recording: None,
278	            calls: Mutex::new(BTreeMap::new()),
279	        };
280	        rpc.call("initialize", Value::Null).await?;
281	        Ok(match tsconfig {
282	            Some(file) => {
283	                let parsed = rpc.call("parseConfigFile", json!({ "file": file })).await?;
284	                parsed.get("options").cloned().unwrap_or_else(default_options)
285	            }
286	            None => default_options(),
287	        })
288	    }
289	
290	    /// A snapshot over `root_files` in a session [`Rpc::prepare`] already initialized.
291	    pub(crate) async fn open_with(
292	        client: Client,
293	        deadline: Duration,
294	        options: &Value,
295	        root_files: &[String],
296	        record: bool,
297	    ) -> Result<Rpc, CallError> {
298	        let mut rpc = Rpc {
299	            client,
300	            deadline,
301	            snapshot: 0,
302	            project: String::new(),
303	            recording: record.then(|| Mutex::new(Vec::new())),
304	            calls: Mutex::new(BTreeMap::new()),
305	        };
306	        let created = rpc
307	            .call(
308	                "createSnapshot",
309	                json!({ "createPrograms": [{ "rootFiles": root_files, "compilerOptions": options }] }),
310	            )
311	            .await?;
312	        let response: SnapshotResponse = decode(created)?;
313	        let project = response
314	            .projects
315	            .into_iter()
316	            .next()
317	            .ok_or_else(|| CallError::Rejected("createSnapshot returned no project".to_string()))?;
318	        rpc.snapshot = response.snapshot;
319	        rpc.project = project.id;
320	        Ok(rpc)
321	    }
