338	    async fn call(&self, method: &str, params: Value) -> Result<Value, CallError> {
339	        if let Ok(mut calls) = self.calls.lock() {
340	            *calls.entry(method.to_string()).or_default() += 1;
341	        }
342	        REQUESTS.try_with(|count| count.fetch_add(1, std::sync::atomic::Ordering::Relaxed)).ok();
343	        let answer = self.client.request(method, params.clone(), self.deadline).await.map_err(classify)?;
344	        if let Some(log) = &self.recording
345	            && let Ok(mut log) = log.lock()
346	        {
347	            log.push(json!({ "method": method, "params": params, "result": answer.value }));
348	        }
349	        Ok(answer.value)
350	    }
