421	    /// Several requests in one round trip. A request the checker rejects fails the batch: nothing here asks for one
422	    /// that may legitimately fail.
423	    pub(crate) async fn batch(&self, requests: Vec<(&str, Value)>) -> Result<Vec<Value>, CallError> {
424	        let wanted = requests.len();
425	        let scoped: Vec<Value> = requests
426	            .into_iter()
427	            .map(|(method, mut params)| {
428	                if let Value::Object(map) = &mut params {
429	                    map.insert("snapshot".to_string(), json!(self.snapshot));
430	                    map.insert("project".to_string(), json!(self.project));
431	                }
432	                json!({ "method": method, "params": params })
433	            })
434	            .collect();
435	        let mut answers = Vec::with_capacity(wanted);
436	        let mut token: Option<String> = None;
437	        loop {
438	            let mut params = json!({ "requests": scoped });
439	            if let (Some(token), Some(map)) = (&token, params.as_object_mut()) {
440	                map.insert("continuationToken".to_string(), json!(token));
441	            }
442	            let page: BatchPage = decode(self.call("batchRequests", params).await?)?;
443	            for response in page.responses {
444	                if let Some(error) = response.error {
445	                    return Err(CallError::Rejected(error));
446	                }
447	                answers.push(response.result);
448	            }
449	            match page.continuation_token {
450	                Some(next) => token = Some(next),
451	                None => break,
452	            }
453	        }
454	        if answers.len() != wanted {
455	            return Err(CallError::Rejected(format!("a batch of {wanted} requests got {} answers", answers.len())));
456	        }
457	        Ok(answers)
458	    }
