31	/// A lazy session with a warm checker, configured as the addon configures it (dependencies loaded, nothing collapsed).
32	fn open(
33	    src: &Utf8PathBuf,
34	    tsc: &str,
35	    env: Vec<(String, String)>,
36	    max_rss_mib: Option<u64>,
37	) -> (WatchSession, Arc<OnDemand>) {
38	    let mut config = OnDemandConfig::new(src.clone());
39	    config.tsconfig = src.ancestors().map(|dir| dir.join("tsconfig.json")).find(|file| file.is_file());
40	    config.tsc_path = Some(Utf8PathBuf::from(tsc));
41	    config.request_timeout = Duration::from_secs(120);
42	    config.extra_env = env;
43	    config.max_rss_mib = max_rss_mib.unwrap_or(config.max_rss_mib);
44	    let checker = Arc::new(OnDemand::new(config));
45	    let options = PipelineOptions {
46	        src_dirs: vec![src.clone()],
47	        load_dependencies: true,
48	        collapse_inherited_props: CollapseInheritedProps::None,
49	        ..PipelineOptions::default()
50	    };
51	    let session = WatchSession::lazy(options).with_semantic(checker.clone(), Duration::from_secs(120));
52	    drop(session.initialize());
53	    (session, checker)
54	}
