60	/// Resident MiB and thread count of a process, from `ps`; `None` once it has gone.
61	fn process_stats(pid: u32) -> Option<(u64, usize)> {
62	    let ps = |args: &[&str]| {
63	        let out = Command::new("ps").args(args).arg("-p").arg(pid.to_string()).output().ok()?;
64	        out.status.success().then(|| String::from_utf8_lossy(&out.stdout).into_owned())
65	    };
66	    let rss: u64 = ps(&["-o", "rss="])?.trim().parse().ok()?;
67	    Some((rss / 1024, ps(&["-M"])?.lines().count().saturating_sub(1)))
68	}
