1	//! One component's props from the checker: the export's call signature, its first parameter's type, that type's
2	//! properties.
3	
4	use std::sync::Arc;
5	
6	use caliper_docgen_core::types::semantic::{PropInterner, SemanticProp};
7	
8	use crate::Target;
9	use crate::convert::{Converter, declared_in, without_undefined};
10	use crate::rpc::{CallError, Rpc, SignatureKind, SymbolInfo, flag};
11	
12	pub(crate) enum Answer {
13	    Props(Vec<Arc<SemanticProp>>),
14	    /// The component keeps its structural result, for this reason.
15	    Fallback(String),
16	}
17	
18	/// What `@types/react` declares (`key`, `ref`, `children` on `PropsWithChildren`, HTML attributes). Reported with the
19	/// flag set when the request asks for the name; what to do with them is the session's policy, not ours.
20	fn is_react_declared(property: &SymbolInfo) -> bool {
21	    property.declarations.iter().any(|declaration| declared_in(declaration).contains("/@types/react/"))
22	}
23	
24	/// The export names a component may have. A display name is not always the export: Mantine sets
25	/// `displayName = "@mantine/core/Accordion"` on the export `Accordion`, and a static one reads `Menu.Item`.
26	fn candidate_names(display_name: &str) -> Vec<&str> {
27	    let mut names = vec![display_name];
28	    for separator in ['/', '.'] {
29	        if let Some((_, last)) = display_name.rsplit_once(separator)
30	            && !last.is_empty()
31	            && !names.contains(&last)
32	        {
33	            names.push(last);
34	        }
35	    }
36	    names
37	}
38	
39	fn fallback(reason: &str) -> Result<Answer, CallError> {
40	    Ok(Answer::Fallback(reason.to_string()))
41	}
42	
43	pub(crate) async fn props_of(
44	    rpc: &Rpc,
45	    converter: &Converter,
46	    interner: &PropInterner,
47	    exports: &[SymbolInfo],
48	    target: &Target,
49	) -> Result<Answer, CallError> {
50	    let display_name = target.display_name.as_str();
51	    let export = candidate_names(display_name)
52	        .into_iter()
53	        .find_map(|name| exports.iter().find(|symbol| symbol.name == name))
54	        .or_else(|| exports.iter().find(|symbol| symbol.name == "default"));
55	    let Some(export) = export else { return fallback("not found among the module's exports") };
56	
57	    let mut reference = export.reference.clone();
58	    if export.flags & flag::SYMBOL_ALIAS != 0 {
59	        reference = rpc.aliased_symbol(&reference).await?.reference;
60	    }
61	
62	    let component = rpc.type_of_symbol(&reference).await?;
63	    let signatures = rpc.signatures(component.id, SignatureKind::Call).await?;
64	    let [signature] = signatures.as_slice() else {
65	        return fallback(if signatures.is_empty() {
66	            "no call signature (class or non-function component)"
67	        } else {
68	            "overloaded call signatures"
69	        });
70	    };
71	    let parameters = rpc.parameters(signature.id).await?;
72	    let Some(first) = parameters.first() else { return fallback("takes no props parameter") };
73	
74	    let props_type = rpc.type_of_symbol(&first.reference).await?;
75	    if props_type.flags & (flag::ANY | flag::UNKNOWN | flag::UNION | flag::TYPE_PARAMETER) != 0 {
76	        return fallback("props type is any, unknown, generic or a union");
77	    }
78	
79	    let own: Vec<SymbolInfo> = rpc
80	        .properties(props_type.id)
81	        .await?
82	        .into_iter()
83	        .filter(|property| {
84	            !is_react_declared(property)
85	                || target.react_wanted.as_ref().is_none_or(|wanted| wanted.contains(&property.name))
86	        })
87	        .collect();
88	    let references: Vec<_> = own.iter().map(|property| &property.reference).collect();
89	    let types = if references.is_empty() { Vec::new() } else { rpc.types_of_symbols(&references).await? };
90	
91	    let converted = converter.convert_roots(&types).await?;
92	    let mut props = Vec::with_capacity(own.len());
93	    for (property, prop_type) in own.iter().zip(converted) {
94	        let required = property.flags & flag::SYMBOL_OPTIONAL == 0;
95	        let react_declared = is_react_declared(property);
96	        props.push(interner.share(SemanticProp {
97	            name: property.name.clone(),
98	            prop_type: without_undefined(prop_type, !required),
99	            required,
100	            react_declared,
101	            // React's own descriptions are the structural pass's to give, and fetching one per attribute is a call each.
102	            description: if react_declared || target.described.contains(&property.name) {
103	                String::new()
104	            } else {
105	                rpc.documentation(&property.reference).await?
106	            },
107	        }));
108	    }
109	    Ok(Answer::Props(props))
110	}
111	
112	#[cfg(test)]
113	mod tests {
114	    use super::*;
115	
116	    fn property(declaration: &str) -> SymbolInfo {
117	        SymbolInfo {
118	            reference: serde_json::Value::Null,
119	            name: "x".to_string(),
120	            flags: 4,
121	            declarations: vec![declaration.to_string()],
122	        }
123	    }
124	
125	    #[test]
126	    fn the_declaring_path_is_what_follows_the_node_id_and_position() {
127	        assert_eq!(
128	            declared_in("48.264./proj/node_modules/@types/react/index.d.ts"),
129	            "/proj/node_modules/@types/react/index.d.ts"
130	        );
131	        assert_eq!(declared_in("garbage"), "");
132	    }
133	
134	    #[test]
135	    fn a_display_name_with_a_package_or_namespace_prefix_also_tries_its_last_segment() {
136	        assert_eq!(candidate_names("Button"), ["Button"]);
137	        assert_eq!(candidate_names("@mantine/core/Accordion"), ["@mantine/core/Accordion", "Accordion"]);
138	        assert_eq!(candidate_names("Menu.Item"), ["Menu.Item", "Item"]);
139	    }
140	
141	    #[test]
142	    fn only_properties_declared_in_types_react_are_excluded() {
143	        assert!(is_react_declared(&property("1.2./p/node_modules/@types/react/index.d.ts")));
144	        assert!(!is_react_declared(&property("1.2./p/src/button.tsx")));
145	        assert!(!is_react_declared(&property("1.2./p/node_modules/@chakra-ui/react/dist/index.d.ts")));
146	    }
147	}
