import sys, collections, json
rows = []
for line in open(sys.argv[1]):
    if not line.startswith('PROF\t'):
        continue
    _, m, us, params, ans = line.rstrip('\n').split('\t', 4)
    rows.append((m, int(us), params, ans))
c = collections.Counter(); t = collections.Counter()
for m, us, p, a in rows:
    c[m] += 1; t[m] += us
print('total', len(rows), 'ms', sum(t.values()) / 1000)
for m, n in c.most_common():
    print(f'{m:32} {n:6} {t[m]/1000:8.1f}ms avg {t[m]/n:6.0f}us')
bc = collections.Counter()
for m, us, p, a in rows:
    if m == 'batchRequests':
        reqs = json.loads(p)['requests']
        bc[tuple(sorted(set(r['method'] for r in reqs)))] += 1
print(bc.most_common(10))

