mod probe {
    use super::*;
    use crate::rpc::flag;
    use serde_json::json;
    use std::time::Instant;

    #[test]
    #[ignore]
    fn probe_floors() {
        let rt = tokio::runtime::Builder::new_current_thread().enable_all().build().unwrap();
        rt.block_on(async {
            let root = Utf8PathBuf::from("/Users/gabe/Projects/caliper-fixtures/gate-large");
            let mut request = SemanticRequest::new(root.clone(), Vec::new());
            request.tsc_path = Some(Utf8PathBuf::from(std::env::var("TSRS").unwrap()));
            let supervisor = Supervisor::spawn(supervisor_config(&request).unwrap()).await.unwrap();
            let file = root.join("src/ChakraButton.tsx").to_string();
            let t = Instant::now();
            let rpc = Arc::new(
                Rpc::open(supervisor.client(), Duration::from_secs(60), Some(root.join("tsconfig.json").as_str()), &[file.clone()], false)
                    .await
                    .unwrap(),
            );
            eprintln!("open {:?}", t.elapsed());
            let exports = module_exports(&rpc, &file).await.unwrap().unwrap();
            let export = exports.iter().find(|s| s.name == "ChakraButton").unwrap();
            let component = rpc.type_of_symbol(&export.reference).await.unwrap();
            let sig = rpc.signatures(component.id, rpc::SignatureKind::Call).await.unwrap();
            let params = rpc.parameters(sig[0].id).await.unwrap();
            let props_type = rpc.type_of_symbol(&params[0].reference).await.unwrap();
            let t = Instant::now();
            let props = rpc.properties(props_type.id).await.unwrap();
            let refs: Vec<_> = props.iter().map(|p| &p.reference).collect();
            let types = rpc.types_of_symbols(&refs).await.unwrap();
            eprintln!("props {} types {:?}", props.len(), t.elapsed());
            let unions: Vec<u64> = types.iter().filter(|t| t.flags & flag::UNION != 0).map(|t| t.id).collect();
            eprintln!("unions {}", unions.len());
            // E2 batch first (cold)
            let t = Instant::now();
            let reqs = unions.iter().map(|id| ("getTypesOfType", json!({ "objectId": id }))).collect();
            let answers = rpc.batch(reqs).await.unwrap();
            eprintln!("E2 batch members cold {:?}", t.elapsed());
            let t = Instant::now();
            for id in &unions { rpc.members(*id).await.unwrap(); }
            eprintln!("E1 sequential members warm {:?}", t.elapsed());
            let t = Instant::now();
            let reqs = unions.iter().map(|id| ("getTypesOfType", json!({ "objectId": id }))).collect();
            rpc.batch(reqs).await.unwrap();
            eprintln!("E2 batch members warm {:?}", t.elapsed());
            let t = Instant::now();
            let mut set = tokio::task::JoinSet::new();
            for id in unions.clone() { let rpc = rpc.clone(); set.spawn(async move { rpc.members(id).await.map(|_| ()) }); }
            while let Some(r) = set.join_next().await { r.unwrap().unwrap(); }
            eprintln!("E3 concurrent members warm {:?}", t.elapsed());
            // second level: objects (mapped) and arrays among members
            let mut objects = Vec::new(); let mut arrays = Vec::new();
            for a in answers {
                let ms: Vec<rpc::TypeInfo> = serde_json::from_value(a).unwrap();
                for m in ms { if m.flags & flag::OBJECT != 0 { if m.object_flags & flag::OBJECT_REFERENCE != 0 { arrays.push(m.id) } else { objects.push(m.id) } } }
            }
            objects.sort(); objects.dedup(); arrays.sort(); arrays.dedup();
            eprintln!("objects {} arrays {}", objects.len(), arrays.len());
            let t = Instant::now();
            let reqs = arrays.iter().map(|id| ("getTypeArguments", json!({ "type": id }))).collect();
            rpc.batch(reqs).await.unwrap();
            eprintln!("E2 batch typeargs cold {:?}", t.elapsed());
            let t = Instant::now();
            for id in &arrays { rpc.type_arguments(*id).await.unwrap(); }
            eprintln!("E1 sequential typeargs warm {:?}", t.elapsed());
            let half = objects.len() / 2;
            let t = Instant::now();
            for id in &objects[..half] { rpc.object_members(*id).await.unwrap(); }
            eprintln!("E1 sequential object_members cold n={} {:?}", half, t.elapsed());
            let t = Instant::now();
            let mut reqs = Vec::new();
            for id in &objects[half..] { reqs.push(("getPropertiesOfType", json!({ "type": id }))); }
            rpc.batch(reqs).await.unwrap();
            eprintln!("E2 batch properties cold n={} {:?}", objects.len() - half, t.elapsed());
            let t = Instant::now();
            for id in &objects[..half] { rpc.properties(*id).await.unwrap(); }
            eprintln!("E1 sequential properties warm n={} {:?}", half, t.elapsed());
            let t = Instant::now();
            for id in &objects[..half] { rpc.type_to_string(*id).await.unwrap(); }
            eprintln!("E1 sequential typeToString n={} {:?}", half, t.elapsed());
            let t = Instant::now();
            let reqs = objects[half..].iter().map(|id| ("typeToString", json!({ "type": id }))).collect();
            rpc.batch(reqs).await.unwrap();
            eprintln!("E2 batch typeToString n={} {:?}", objects.len() - half, t.elapsed());
            let t = Instant::now();
            for p in &props { rpc.documentation(&p.reference).await.unwrap(); }
            eprintln!("E1 docs n={} {:?}", props.len(), t.elapsed());
            let t = Instant::now();
            let reqs = props.iter().map(|p| ("getDocumentationComment", json!({ "symbol": p.reference }))).collect();
            rpc.batch(reqs).await.unwrap();
            eprintln!("E2 batch docs {:?}", t.elapsed());
            let t = Instant::now();
            for _ in 0..1000 { rpc.type_arguments(arrays[0]).await.unwrap(); }
            eprintln!("1000 trivial round trips {:?}", t.elapsed());
        });
    }
}
