#[ignore]
fn probe_floors() {
    let rt = tokio::runtime::Builder::new_current_thread().enable_all().build().unwrap();
    rt.block_on(async {
        let root = Utf8PathBuf::from("/Users/gabe/Projects/caliper-fixtures/gate-large");
