            Rpc::open(
                supervisor.client(),
                Duration::from_secs(60),
                Some(root.join("tsconfig.json").as_str()),
                &[file.clone()],
                false,
            )
            .await
            .unwrap(),
        );
        eprintln!("open {:?}", t.elapsed());
