        let export = exports.iter().find(|s| s.name == "ChakraButton").unwrap();
        let component = rpc.type_of_symbol(&export.reference).await.unwrap();
        let sig = rpc.signatures(component.id, rpc::SignatureKind::Call).await.unwrap();
        let params = rpc.parameters(sig[0].id).await.unwrap();
        let props_type = rpc.type_of_symbol(&params[0].reference).await.unwrap();
        let t = Instant::now();
        let props = rpc.properties(props_type.id).await.unwrap();
        let refs: Vec<_> = props.iter().map(|p| &p.reference).collect();
        let types = rpc.types_of_symbols(&refs).await.unwrap();
        eprintln!("props {} types {:?}", props.len(), t.elapsed());
        let unions: Vec<u64> = types.iter().filter(|t| t.flags & flag::UNION != 0).map(|t| t.id).collect();
        eprintln!("unions {}", unions.len());
        let t = Instant::now();
        let reqs = unions.iter().map(|id| ("getTypesOfType", json!({ "objectId": id }))).collect();
        let answers = rpc.batch(reqs).await.unwrap();
