        for id in &unions {
            rpc.members(*id).await.unwrap();
        }
        eprintln!("E1 sequential members warm {:?}", t.elapsed());
        let t = Instant::now();
        let reqs = unions.iter().map(|id| ("getTypesOfType", json!({ "objectId": id }))).collect();
