        for id in unions.clone() {
            let rpc = rpc.clone();
            set.spawn(async move { rpc.members(id).await.map(|_| ()) });
        }
        while let Some(r) = set.join_next().await {
            r.unwrap().unwrap();
        }
        eprintln!("E3 concurrent members warm {:?}", t.elapsed());
        let mut objects = Vec::new();
        let mut arrays = Vec::new();
        for a in answers {
            let ms: Vec<rpc::TypeInfo> = serde_json::from_value(a).unwrap();
            for m in ms {
                if m.flags & flag::OBJECT != 0 {
                    if m.object_flags & flag::OBJECT_REFERENCE != 0 {
                        arrays.push(m.id)
                    } else {
                        objects.push(m.id)
                    }
                }
            }
