        }
        rpc.batch(reqs).await.unwrap();
        eprintln!("E2 batch properties cold n={} {:?}", objects.len() - half, t.elapsed());
        let t = Instant::now();
        for id in &objects[..half] {
            rpc.properties(*id).await.unwrap();
        }
        eprintln!("E1 sequential properties warm n={} {:?}", half, t.elapsed());
        let t = Instant::now();
        for id in &objects[..half] {
            rpc.type_to_string(*id).await.unwrap();
        }
        eprintln!("E1 sequential typeToString n={} {:?}", half, t.elapsed());
        let t = Instant::now();
        let reqs = objects[half..].iter().map(|id| ("typeToString", json!({ "type": id }))).collect();
        rpc.batch(reqs).await.unwrap();
        eprintln!("E2 batch typeToString n={} {:?}", objects.len() - half, t.elapsed());
        let t = Instant::now();
        for p in &props {
            rpc.documentation(&p.reference).await.unwrap();
        }
        eprintln!("E1 docs n={} {:?}", props.len(), t.elapsed());
        let t = Instant::now();
        let reqs = props.iter().map(|p| ("getDocumentationComment", json!({ "symbol": p.reference }))).collect();
        rpc.batch(reqs).await.unwrap();
        eprintln!("E2 batch docs {:?}", t.elapsed());
        let t = Instant::now();
        for _ in 0..1000 {
            rpc.type_arguments(arrays[0]).await.unwrap();
        }
        eprintln!("1000 trivial round trips {:?}", t.elapsed());
    });
}

