        let client = supervisor.client();
        let mut requests = Vec::new();
        for (method, params, _) in &rows {
            if method == "batchRequests" {
                requests.extend(params["requests"].as_array().unwrap().iter().cloned());
            } else {
                requests.push(serde_json::json!({ "method": method, "params": params }));
