        for (_, _, answer) in &rows {
            total += answer.len();
            let v: Value = serde_json::from_str(answer).unwrap();
            let v2: Value = serde_json::from_value(v).unwrap();
            std::hint::black_box(v2);
        }
        eprintln!("parse to Value twice, {total} bytes: {:?}", t.elapsed());
        let t = Instant::now();
        for (_, _, answer) in &rows {
            let v: serde_json::value::RawValue = *Box::<serde_json::value::RawValue>::from(
                serde_json::from_str::<Box<serde_json::value::RawValue>>(answer).unwrap(),
            )
            .into();
            std::hint::black_box(&v);
        }
        eprintln!("raw scan: {:?}", t.elapsed());
    });
}

