// TEMPORARY profiling probe, not committed: replays the logged requests of one first answer three ways.
use super::*;
use serde_json::Value;
use std::time::Instant;

fn logged() -> Vec<(String, Value, String)> {
    let path = std::env::var("PROF_LOG").unwrap();
    let mut rows = Vec::new();
    for line in std::fs::read_to_string(path).unwrap().lines() {
        let Some(rest) = line.strip_prefix("PROF\t") else { continue };
        let mut parts = rest.splitn(4, '\t');
        let method = parts.next().unwrap().to_string();
        let _us = parts.next();
        let params: Value = serde_json::from_str(parts.next().unwrap()).unwrap();
        let answer = parts.next().unwrap().to_string();
        rows.push((method, params, answer));
    }
    rows
}

async fn fresh() -> (Supervisor, Vec<(String, Value, String)>) {
    let root = Utf8PathBuf::from("/Users/gabe/Projects/caliper-fixtures/gate-large");
    let mut request = SemanticRequest::new(root, Vec::new());
    request.tsc_path = Some(Utf8PathBuf::from(std::env::var("TSRS").unwrap()));
    let supervisor = Supervisor::spawn(supervisor_config(&request).unwrap()).await.unwrap();
    let rows = logged();
    let client = supervisor.client();
    let mut setup = 0;
    for (index, (method, params, _)) in rows.iter().enumerate() {
        let t = Instant::now();
        client.request(method, params.clone(), Duration::from_secs(60)).await.unwrap();
        if method == "createSnapshot" {
            eprintln!("createSnapshot {:?}", t.elapsed());
            setup = index + 1;
            break;
        }
    }
    let rest = rows[setup..].iter().filter(|(m, _, _)| m != "release").cloned().collect();
    (supervisor, rest)
}

#[test]
#[ignore]
fn probe_replay() {
    let rt = tokio::runtime::Builder::new_current_thread().enable_all().build().unwrap();
    rt.block_on(async {
        // (a) sequential, as the converter does.
        let (supervisor, rows) = fresh().await;
        let client = supervisor.client();
        let t = Instant::now();
        let mut mismatched = 0;
        for (method, params, answer) in &rows {
            let got = client.request(method, params.clone(), Duration::from_secs(60)).await.unwrap();
            if got.value.to_string() != *answer {
                mismatched += 1;
            }
        }
        eprintln!("(a) sequential {} requests {:?} mismatched {mismatched}", rows.len(), t.elapsed());
        drop(supervisor);

        // (b) pipelined in the same order.
        let (supervisor, rows) = fresh().await;
        let client = supervisor.client();
        let t = Instant::now();
        let mut set = tokio::task::JoinSet::new();
        for (index, (method, params, _)) in rows.iter().cloned().enumerate() {
            let client = client.clone();
            set.spawn(async move { (index, client.request(&method, params, Duration::from_secs(60)).await) });
        }
        let mut answers = vec![String::new(); rows.len()];
        while let Some(joined) = set.join_next().await {
            let (index, got) = joined.unwrap();
            answers[index] = got.unwrap().value.to_string();
        }
        let mismatched = answers.iter().zip(&rows).filter(|(a, r)| **a != r.2).count();
        eprintln!("(b) pipelined {:?} mismatched {mismatched}", t.elapsed());
        drop(supervisor);

        // (c) one batch, the inner batches flattened, in the same order.
        let (supervisor, rows) = fresh().await;
        let client = supervisor.client();
        let mut requests = Vec::new();
        for (method, params, _) in &rows {
            if method == "batchRequests" {
                requests.extend(params["requests"].as_array().unwrap().iter().cloned());
            } else {
                requests.push(serde_json::json!({ "method": method, "params": params }));
            }
        }
        let t = Instant::now();
        let mut token: Option<String> = None;
        let mut pages = 0;
        let mut bytes = 0;
        loop {
            let mut params = serde_json::json!({ "requests": requests });
            if let Some(token) = &token {
                params["continuationToken"] = serde_json::json!(token);
            }
            let page = client.request("batchRequests", params, Duration::from_secs(60)).await.unwrap().value;
            pages += 1;
            bytes += page.to_string().len();
            match page.get("continuationToken").and_then(Value::as_str) {
                Some(next) => token = Some(next.to_string()),
                None => break,
            }
        }
        eprintln!("(c) one batch of {} in {pages} pages, {bytes} bytes: {:?}", requests.len(), t.elapsed());
        drop(supervisor);

        // Client parse: the logged answers, three walks as now, and one typed walk.
        let rows = logged();
        let mut total = 0;
        let t = Instant::now();
        for (_, _, answer) in &rows {
            total += answer.len();
            let v: Value = serde_json::from_str(answer).unwrap();
            let v2: Value = serde_json::from_value(v).unwrap();
            std::hint::black_box(v2);
        }
        eprintln!("parse to Value twice, {total} bytes: {:?}", t.elapsed());
        let t = Instant::now();
        for (_, _, answer) in &rows {
            let v: serde_json::value::RawValue = *Box::<serde_json::value::RawValue>::from(
                serde_json::from_str::<Box<serde_json::value::RawValue>>(answer).unwrap(),
            )
            .into();
            std::hint::black_box(&v);
        }
        eprintln!("raw scan: {:?}", t.elapsed());
    });
}

