        Some(version) => {
            request.tsc_path = Some(checker.join("bin/tsc"));
            request.expected_versions = Box::leak(vec![&*Box::leak(version.into_boxed_str())].into_boxed_slice());
        }
        None => request.tsc_path = Some(checker),
