#[derive(Debug, Clone)]
pub struct Notification {
    /// The notification's method name, as `tsc` sent it.
    pub method: String,
    /// The notification's parameters; `null` when it sent none.
    pub params: serde_json::Value,
}

#[derive(Debug)]
pub enum IncomingMessage {
    Response(ResponseMessage),
