#[test]
fn a_response_keeps_its_result_as_the_text_it_arrived_as() {
    let Ok(IncomingMessage::Response(response)) =
        parse_incoming(br#"{"id": 4, "result": {"b": [1, 2.50], "a": "x"}}"#)
    else {
