58	/// The outcome of one run, and how many calls the backend made to the checker.
59	struct Run {
60	    outcome: SemanticOutcome,
61	    round_trips: usize,
62	}
63	
64	/// Asks the checker about every component of `fixture`: replayed, or live (`reverse`: asked last to first).
65	fn run(fixture: &str, live: Option<(&Utf8PathBuf, bool)>) -> Run {
66	    let project = project(fixture, live.is_none());
67	    let output = structural(&project);
68	    let calls = project.root.join("calls.json");
69	    let mut request = SemanticRequest::new(project.root.clone(), targets_of(&output));
70	    request.request_timeout = Duration::from_secs(60);
71	    request.record_to = Some(calls.clone());
72	    match live {
73	        None => {
74	            request.expected_versions = &[FAKE_VERSION];
75	            request.extra_env.push((
76	                "REPLAY_FIXTURE".to_string(),
77	                format!("{}/tests/fixtures/{fixture}.recording.json", env!("CARGO_MANIFEST_DIR")),
78	            ));
79	        }
80	        Some((bin, reverse)) => {
81	            request.tsc_path = Some(bin.clone());
82	            request.reverse_queries = reverse;
83	        }
84	    }
85	    let outcome = resolve(request);
86	    assert_eq!(outcome.diagnostics, []);
87	    assert_eq!(outcome.fallbacks, []);
88	    let recorded: Vec<Value> = serde_json::from_str(&std::fs::read_to_string(calls).unwrap()).unwrap();
89	    Run { outcome, round_trips: recorded.len() }
90	}
91	
92	/// Every way to ask: replayed, and with `TSRS_BIN` live, first to last and last to first.
93	fn each_way(fixture: &str, check: impl Fn(&Run, &str)) {
94	    check(&run(fixture, None), "replayed");
95	    let Some(bin) = tsrs_bin() else { return };
96	    for reverse in [false, true] {
97	        check(&run(fixture, Some((&bin, reverse))), if reverse { "live, last to first" } else { "live" });
98	    }
99	}
100	
101	fn prop_type(outcome: &SemanticOutcome, component: &str, prop: &str) -> Value {
102	    let component = outcome
103	        .components
104	        .iter()
105	        .find(|candidate| candidate.display_name == component)
106	        .unwrap_or_else(|| panic!("{component} is in the answer"));
107	    let prop = component.props.iter().find(|candidate| candidate.name == prop).unwrap();
108	    serde_json::to_value(&prop.prop_type).unwrap()
109	}
110	
111	/// The most round trips the `memo` fixture takes with the memo shared across contexts: it takes 274, where keyed by the
112	/// whole enclosing context it takes 1,211.
113	const ROUND_TRIPS: usize = 300;
114	
115	/// A type that many different types enclose is converted once, not once under each: sixteen interfaces and twelve
116	/// aliases of a union all hold the same big object, and so do `Box<T>` instantiated under one another.
117	#[test]
118	fn a_type_many_types_enclose_is_converted_once() {
119	    each_way("memo", |run, how| {
120	        assert!(run.round_trips <= ROUND_TRIPS, "{how}: {} round trips, at most {ROUND_TRIPS}", run.round_trips);
121	
122	        // What was shared is still what each place holds.
123	        let shared = |component: &str, prop: &str, pointer: &str| {
124	            let ty = prop_type(&run.outcome, component, prop);
125	            ty.pointer(pointer).unwrap_or_else(|| panic!("{pointer} is in {ty}")).clone()
126	        };
127	        let first = shared("Many", "w1", "/fields/0/propType");
128	        assert_eq!(first["kind"], "object", "{how}");
129	        for index in 2..=16 {
130	            assert_eq!(shared("Many", &format!("w{index}"), "/fields/0/propType"), first, "{how}: w{index}");
131	        }
132	        // At the same depth, whichever instantiation of `Box` it is in.
133	        assert_eq!(shared("Many", "box1", "/fields/1/propType"), first, "{how}");
134	        assert_eq!(shared("Many", "box3", "/fields/0/propType/fields/1/propType")["kind"], "object", "{how}");
135	        // A union's members all hold it, one level further down.
136	        let member = shared("Unions", "wide", "/members/0/fields/1/propType");
137	        assert_eq!(member["kind"], "object", "{how}");
138	        for index in 1..12 {
139	            assert_eq!(shared("Unions", "wide", &format!("/members/{index}/fields/1/propType")), member, "{how}");
140	        }
141	    });
142	}
143	
144	fn field(name: &str, prop_type: Value) -> Value {
145	    json!({ "name": name, "propType": prop_type, "required": true, "description": "" })
146	}
147	
148	fn object(fields: Vec<Value>) -> Value {
149	    json!({ "kind": "object", "fields": fields })
150	}
151	
152	fn recursive(name: &str) -> Value {
153	    json!({ "kind": "recursive", "name": name, "args": [] })
154	}
