156	/// `Node1` and `Node2` contain each other. Each is a back-reference only inside the other, and a type that was
157	/// converted outside the cycle (`Holder`, whose `Node2` is not inside `Node1`) is not reused inside it, nor the other
158	/// way round, whichever of the two the memo saw first.
159	#[test]
160	fn a_type_inside_and_outside_a_cycle_is_a_back_reference_only_inside() {
161	    let number = json!({ "kind": "number" });
162	    let string = json!({ "kind": "string" });
163	    // `Node1` as a prop: its `Node2` sits inside it, so that one's `back` points back.
164	    let node1 = object(vec![
165	        field("next", object(vec![field("back", recursive("Node1")), field("tag", string.clone())])),
166	        field("id", number.clone()),
167	    ]);
168	    // `Node2` as a prop: the mirror image.
169	    let node2 = object(vec![
170	        field("back", object(vec![field("next", recursive("Node2")), field("id", number)])),
171	        field("tag", string),
172	    ]);
173	    // `Holder` encloses neither: its `Node2` is the same as the prop's, expanded all the way to the lap.
174	    let expected = [
175	        ("holder", object(vec![field("held", node2.clone())])),
176	        ("first", node1.clone()),
177	        ("second", node2.clone()),
178	        ("wrapped", object(vec![field("inner", node1.clone())])),
179	        ("both", object(vec![field("a", node1), field("b", node2)])),
180	    ];
181	    each_way("cycles", |run, how| {
182	        for component in ["OutsideFirst", "InsideFirst"] {
183	            for (prop, want) in &expected {
184	                assert_eq!(&prop_type(&run.outcome, component, prop), want, "{how}: {component}.{prop}");
185	            }
186	        }
187	    });
188	}
