/// A component's descriptions are asked for together: one batch per component that has a prop to describe, never a
/// request per prop. Chakra's `ButtonProps` has 852 props, and one request each was 30 ms of its first answer.
#[test]
fn a_components_descriptions_take_one_round_trip() {
    for fixture in ["memo", "families"] {
        each_way(fixture, |run, how| {
            let alone = run.calls.iter().filter(|call| call["method"] == "getDocumentationComment").count();
            let batches: Vec<usize> = run
                .calls
                .iter()
                .filter(|call| call["method"] == "batchRequests")
                .map(|call| {
                    let requests = call["params"]["requests"].as_array().map(Vec::as_slice).unwrap_or_default();
                    requests.iter().filter(|request| request["method"] == "getDocumentationComment").count()
                })
                .filter(|asked| *asked > 0)
                .collect();
            let components = run.outcome.components.len();
            assert_eq!(alone, 0, "{fixture}, {how}: descriptions asked for one at a time");
            assert!(!batches.is_empty(), "{fixture}, {how}: no description was asked for");
            assert!(batches.len() <= components, "{fixture}, {how}: {batches:?} batches for {components} components");
        });
    }
}

