 }
@@ -446,6 +465,23 @@ impl Converter {
         Ok(text)
     }

+    /// The members or type arguments of a type, asked once per type however many conversions read them.
+    async fn parts(&self, id: u64, kind: Parts) -> Result<Arc<[TypeInfo]>, CallError> {
+        let key = (id, kind);
+        if let Some(known) = self.state.parts.lock().ok().and_then(|parts| parts.get(&key).cloned()) {
+            return Ok(known);
+        }
+        let fetched: Arc<[TypeInfo]> = match kind {
+            Parts::Members => self.rpc.members(id).await?,
+            Parts::Arguments => self.rpc.type_arguments(id).await?,
+        }
+        .into();
+        if let Ok(mut parts) = self.state.parts.lock() {
+            parts.insert(key, fetched.clone());
+        }
+        Ok(fetched)
+    }
