/// What a type's parts are does not change inside a snapshot, so a type converted again inside one component's answer
/// (the memo is keyed by depth too) does not ask the checker for its members or type arguments a second time. Each
/// repeat is a round trip, and on Chakra's style props, where every prop's union holds the same members again one level
/// down, they were one in eight. In `memo` no two components share such a type, so no request is repeated at all.
#[test]
fn the_parts_of_a_type_are_asked_for_once() {
    each_way("memo", |run, how| {
        let mut seen = std::collections::BTreeMap::new();
        for call in &run.calls {
            let method = call["method"].as_str().unwrap_or_default();
            if matches!(method, "getTypesOfType" | "getTypeArguments") {
                *seen.entry((method.to_string(), call["params"].to_string())).or_insert(0) += 1;
            }
        }
        let repeated: Vec<String> = seen
            .iter()
            .filter(|(_, count)| **count > 1)
            .map(|((method, params), count)| format!("{method} {params} x{count}"))
            .collect();
        assert!(!seen.is_empty(), "{how}: no parts were asked for");
        assert_eq!(repeated, Vec::<String>::new(), "{how}");
    });
}

